### 3. The External Recovery Tool (Python)

This tool is used for Requirement 5 (Corruption) and Requirement 6 (Repair) because it can manipulate the `fs.img` while the OS is not running, which is safer for recovery operations.

```python
import struct
import os
import sys

# xv6 Constants
BSIZE = 1024
IPB = BSIZE // 64 
ROOTINO = 1

class XV6RecoveryTool:
    def __init__(self, image_path):
        self.image_path = image_path
        self.f = open(image_path, "rb+")
        self.read_superblock()

    def read_superblock(self):
        self.f.seek(BSIZE)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.ninodes = sb[3]
        self.inodestart = sb[6]

    def get_inode(self, inum):
        offset = (self.inodestart * BSIZE) + (inum * 64)
        self.f.seek(offset)
        data = self.f.read(64)
        # type (h), major (h), minor (h), nlink (h), size (I), addrs (13I)
        res = struct.unpack("<hhhhI13I", data)
        return {"inum": inum, "type": res[0], "size": res[4], "addrs": res[5:]}

    def corrupt_inode(self, inum):
        """Requirement 5: Erase inode info"""
        offset = (self.inodestart * BSIZE) + (inum * 64)
        self.f.seek(offset)
        self.f.write(b'\x00' * 64)
        self.f.flush()
        print(f"Successfully corrupted Inode {inum}")

    def repair_fs(self):
        """Requirement 6: Reachability Analysis"""
        print("Scanning for orphaned inodes...")
        allocated = []
        for i in range(1, self.ninodes):
            ino = self.get_inode(i)
            if ino['type'] != 0:
                allocated.append(i)

        # Simplified reachability (DFS)
        reachable = {ROOTINO}
        # ... (Logic to traverse directory blocks and add to reachable set)

        orphans = set(allocated) - reachable
        if orphans:
            print(f"Found orphans: {orphans}. Suggestion: Link to /lost+found")
        else:
            print("File system tree is healthy.")

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python recovery.py [walk|corrupt|repair] [inum]")
    else:
        tool = XV6RecoveryTool("fs.img")
        cmd = sys.argv[1]
        if cmd == "corrupt":
            tool.corrupt_inode(int(sys.argv[2]))
        elif cmd == "repair":
            tool.repair_fs()
```

