To complete the `ncpmvdir` utility, we need to implement the logic for path validation, directory traversal using `nftw()`, file copying, and conditional deletion for the move operation.

The following implementation includes:
1.  **Path Validation**: Ensures both source and destination are within the `$HOME` directory using `realpath()`.
2.  **Directory Creation**: A helper to ensure the destination path exists.
3.  **Extension Filtering**: Logic to skip files ending in the specified extensions.
4.  **File Copying**: A manual byte-copy function to replicate file contents and permissions.
5.  **Move Logic**: If `-mv` is selected, a second `nftw()` pass (using `FTW_DEPTH`) is performed to delete the source tree after the copy is complete.

```python
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <ftw.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <libgen.h>
#include <limits.h>
#include <fcntl.h>
#include <errno.h>

// Global variables for nftw callback access
char g_src_path[PATH_MAX];
char g_dst_path[PATH_MAX];
char g_extensions[6][10];
int g_ext_count = 0;
int g_is_move = 0;

// Helper to check if a path is within the home directory
int is_in_home(const char *path) {
    char absolute_path[PATH_MAX];
    char *home = getenv("HOME");
    if (!home) return 0;

    if (realpath(path, absolute_path) == NULL) {
        // If path doesn't exist yet (like destination), check its parent
        char temp[PATH_MAX];
        strncpy(temp, path, PATH_MAX);
        char *parent = dirname(temp);
        if (realpath(parent, absolute_path) == NULL) return 0;
    }

    return strncmp(absolute_path, home, strlen(home)) == 0;
}

// Helper to copy file content
int copy_file(const char *src, const char *dst, mode_t mode) {
    int src_fd = open(src, O_RDONLY);
    if (src_fd < 0) return -1;

    int dst_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (dst_fd < 0) {
        close(src_fd);
        return -1;
    }

    char buffer[4096];
    ssize_t nread;
    while ((nread = read(src_fd, buffer, sizeof(buffer))) > 0) {
        write(dst_fd, buffer, nread);
    }

    close(src_fd);
    close(dst_fd);
    return 0;
}

// Helper to check if file has an excluded extension
int is_excluded(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (!dot) return 0;
    dot++; // skip the dot

    for (int i = 0; i < g_ext_count; i++) {
        if (strcmp(dot, g_extensions[i]) == 0) return 1;
    }
    return 0;
}

// nftw callback for copying
int copy_callback(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    // Construct destination path
    char target_path[PATH_MAX];
    snprintf(target_path, sizeof(target_path), "%s%s", g_dst_path, fpath + strlen(g_src_path));

    if (typeflag == FTW_D) {
        // Create directory with same permissions
        mkdir(target_path, sb->st_mode);
    } else if (typeflag == FTW_F) {
        if (!is_excluded(fpath)) {
            if (copy_file(fpath, target_path, sb->st_mode) != 0) {
                fprintf(stderr, "Error copying file: %s\n", fpath);
            }
        }
    }
    return 0;
}

// nftw callback for deleting (used for -mv)
int delete_callback(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    if (remove(fpath) != 0) {
        perror("Error deleting source item");
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s [source_dir] [destination_dir] [options] <extension list>\n", argv[0]);
        return 1;
    }

    char *src_arg = argv[1];
    char *dst_arg = argv[2];
    char *opt_arg = argv[3];

    // Resolve absolute source path
    if (realpath(src_arg, g_src_path) == NULL) {
        perror("Source directory error");
        return 1;
    }

    // Validate Home Directory Hierarchy
    if (!is_in_home(src_arg)) {
        fprintf(stderr, "Error: Source must be in home directory.\n");
        return 1;
    }

    // Prepare destination path
    // If destination doesn't exist, we'll create it during nftw
    // But we need the absolute path string for mapping
    if (dst_arg[0] == '~') {
        snprintf(g_dst_path, PATH_MAX, "%s%s", getenv("HOME"), dst_arg + 1);
    } else {
        // Use a simplified absolute path logic for destination
        if (dst_arg[0] == '/') strncpy(g_dst_path, dst_arg, PATH_MAX);
        else {
            getcwd(g_dst_path, PATH_MAX);
            strcat(g_dst_path, "/");
            strcat(g_dst_path, dst_arg);
        }
    }

    if (!is_in_home(g_dst_path)) {
        fprintf(stderr, "Error: Destination must be in home directory.\n");
        return 1;
    }

    // Parse options
    if (strcmp(opt_arg, "-cp") == 0) {
        g_is_move = 0;
    } else if (strcmp(opt_arg, "-mv") == 0) {
        g_is_move = 1;
    } else {
        fprintf(stderr, "Invalid option: %s. Use -cp or -mv.\n", opt_arg);
        return 1;
    }

    // Parse extensions
    for (int i = 4; i < argc && g_ext_count < 6; i++) {
        strncpy(g_extensions[g_ext_count++], argv[i], 9);
    }

    // Create destination root if it doesn't exist
    struct stat st = {0};
    if (stat(g_dst_path, &st) == -1) {
        if (mkdir(g_dst_path, 0755) != 0) {
            // If parent directories are missing, this simple mkdir might fail.
            // In a production tool, one would implement a recursive mkdir -p.
            perror("Failed to create destination directory");
            return 1;
        }
    }

    // Walk the tree and copy
    if (nftw(g_src_path, copy_callback, 20, FTW_PHYS) == -1) {
        perror("nftw failed");
        return 1;
    }

    // If move, delete the source tree
    if (g_is_move) {
        // FTW_DEPTH ensures we delete files before directories
        if (nftw(g_src_path, delete_callback, 20, FTW_PHYS | FTW_DEPTH) == -1) {
            perror("Cleanup failed");
            return 1;
        }
    }

    printf("Operation completed successfully.\n");
    return 0;
}
```

### Key Implementation Details:
- **`nftw` Flags**: We use `FTW_PHYS` to avoid following symbolic links (preventing infinite loops or escaping the home directory). For deletion, we use `FTW_DEPTH` to process children before parents.
- **Path Mapping**: Inside `copy_callback`, we calculate the relative path of the current item by stripping the `g_src_path` prefix and appending the remainder to `g_dst_path`.
- **Extension Logic**: The `is_excluded` function finds the last dot in the filename and compares the substring against the provided list.
- **Move vs. Copy**: Since the requirement specifies excluding files during a move, we cannot use the standard `rename()` system call (which moves everything). Instead, we copy the allowed items and then perform a post-order traversal to delete the source.

