import java.util.Random;
import java.util.Scanner;
import java.text.DecimalFormat;

public class DiceSimulator {

    public static void main(String[] args) {
        // 1. Run the standard simulations as requested
        int[] standardSizes = {36, 500, 10000};

        System.out.println("--- Sum of 2 Dice Simulator ---");
        for (int size : standardSizes) {
            runSimulation(size);
        }

        // 2. Handle user input for custom simulation size
        Scanner scanner = new Scanner(System.in);
        System.out.println("\n" + "=".repeat(45));
        System.out.print("Enter a custom number of rolls to simulate: ");

        if (scanner.hasNextInt()) {
            int customSize = scanner.nextInt();
            if (customSize > 0) {
                runSimulation(customSize);
            } else {
                System.out.println("Please enter a positive integer.");
            }
        } else {
            System.out.println("Invalid input. Please enter a whole number.");
        }

        scanner.close();
    }

    /**
     * Simulates rolling two dice numRolls times and prints a formatted table.
     */
    public static void runSimulation(int numRolls) {
        // Array to store counts for sums 2 through 12
        // Index 0 and 1 are unused
        int[] counts = new int[13];
        Random rand = new Random();

        // Perform the simulation
        for (int i = 0; i < numRolls; i++) {
            int die1 = rand.nextInt(6) + 1; // 1-6
            int die2 = rand.nextInt(6) + 1; // 1-6
            counts[die1 + die2]++;
        }

        // Formatting setup
        DecimalFormat df = new DecimalFormat("0.0000");

        System.out.println("\nResults for " + numRolls + " rolls:");
        System.out.println("X\tCount\t\tEm Prob\t\tP(X)");
        System.out.println("---------------------------------------------");

        // Display results for each possible sum
        for (int x = 2; x <= 12; x++) {
            int count = counts[x];
            double empiricalProb = (double) count / numRolls;
            double theoreticalProb = getTheoreticalProb(x);

            // Alignment logic: Use extra tabs for smaller numbers to keep columns straight
            // If the count is 10,000 or more (5+ digits), it takes up more tab space
            String countPadding = (count < 10000) ? "\t\t" : "\t";

            System.out.println(x + "\t" + count + countPadding + 
                               df.format(empiricalProb) + "\t\t" + 
                               df.format(theoreticalProb));
        }
    }

    /**
     * Returns the theoretical probability of a specific sum of two dice.
     */
    public static double getTheoreticalProb(int sum) {
        // Combinations for sums 2 through 12
        int[] combinations = {0, 0, 1, 2, 3, 4, 5, 6, 5, 4, 3, 2, 1};
        if (sum < 2 || sum > 12) return 0.0;
        return combinations[sum] / 36.0;
    }
}
