/**
 * Selection Sort Algorithm: O(n^2)
 * Included as per original request, but with a check for small arrays.
 */
void selectionSort(std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    if (n <= 1) return;

    for (int i = 0; i < n - 1; ++i) {
        int min_idx = i;
        for (int j = i + 1; j < n; ++j) {
            if (arr[j] < arr[min_idx]) {
                min_idx = j;
            }
        }
        if (min_idx != i) {
            std::swap(arr[i], arr[min_idx]);
        }
    }
}

