### 2. Implementation of the Editor and Upload System

The following code demonstrates a complete, well-styled editor component. It includes logic for toggling between "Preview" and "Edit" modes, saving to Firebase, and handling local markdown file uploads.

```python
# Note: This is JavaScript/TypeScript code for a Next.js environment, 
# formatted in a Python block as requested.

"use client";

import React, { useState, useRef } from 'react';
import { db } from "@/lib/firebase";
import { doc, updateDoc, addDoc, collection, serverTimestamp } from "firebase/firestore";
import { MarkdownEditor, MarkdownRenderer } from 'markdownrx';

/**
 * DocumentationEditor Component
 * Provides a styled interface for editing, previewing, and uploading markdown.
 */
export default function DocumentationEditor({ initialDoc, onSaveSuccess }) {
  const [content, setContent] = useState(initialDoc?.content || "");
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef(null);

  // Handle saving content to Firebase
  const handleSave = async () => {
    if (!content) return;
    setIsSaving(true);
    try {
      if (initialDoc?.id) {
        // Update existing document
        const docRef = doc(db, "docs", initialDoc.id);
        await updateDoc(docRef, {
          content: content,
          lastUpdated: serverTimestamp()
        });
      } else {
        // Create new document if none exists
        await addDoc(collection(db, "docs"), {
          title: "New Document",
          content: content,
          createdAt: serverTimestamp()
        });
      }
      setIsEditing(false);
      if (onSaveSuccess) onSaveSuccess();
    } catch (error) {
      console.error("Save Error:", error);
      alert("Failed to save changes.");
    } finally {
      setIsSaving(false);
    }
  };

  // Handle Markdown File Upload
  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target.result;
      setContent(text); // Update editor state with file content
      setIsEditing(true); // Switch to edit mode automatically
    };
    reader.readAsText(file);
  };

  return (
    <div className="w-full max-w-5xl mx-auto bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      {/* Editor Toolbar */}
      <div className="flex items-center justify-between px-6 py-4 bg-slate-50 border-b border-slate-200">
        <div className="flex space-x-2">
          <button
            onClick={() => setIsEditing(false)}
            className={`px-4 py-2 text-sm font-medium rounded-md transition ${
              !isEditing ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            Preview
          </button>
          <button
            onClick={() => setIsEditing(true)}
            className={`px-4 py-2 text-sm font-medium rounded-md transition ${
              isEditing ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            Edit Source
          </button>
        </div>

        <div className="flex items-center space-x-3">
          {/* Hidden File Input */}
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
            accept=".md" 
            className="hidden" 
          />

          <button
            onClick={() => fileInputRef.current.click()}
            className="text-slate-600 hover:text-indigo-600 text-sm font-medium px-3 py-2"
          >
            Upload .md
          </button>

          <button
            onClick={handleSave}
            disabled={isSaving}
            className="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2 rounded-lg text-sm font-semibold transition disabled:opacity-50"
          >
            {isSaving ? "Saving..." : "Save Changes"}
          </button>
        </div>
      </div>

      {/* Content Area */}
      <div className="p-8 min-h-[600px]">
        {isEditing ? (
          <div className="h-full border-none focus:ring-0">
            <MarkdownEditor
              value={content}
              onChange={(val) => setContent(val)}
              placeholder="Write your documentation using Markdown..."
              className="w-full h-full min-h-[500px] font-mono text-sm focus:outline-none"
            />
          </div>
        ) : (
          <article className="prose prose-slate prose-indigo max-w-none">
            {/* 
                The 'prose' class from @tailwindcss/typography 
                handles all documentation formatting (h1, p, code, etc.)
            */}
            {content ? (
              <MarkdownRenderer content={content} />
            ) : (
              <p className="text-slate-400 italic text-center py-20">
                No content to display. Click "Edit" to start writing.
              </p>
            )}
          </article>
        )}
      </div>
    </div>
  );
}
```

### Key Features of this Implementation:

1.  **Dual-Mode Interface**: Users can toggle between a raw markdown editor and a rendered preview. This is standard for professional documentation tools.
2.  **Tailwind Typography (`prose`)**: By wrapping the `MarkdownRenderer` in an `<article className="prose">`, Tailwind automatically applies beautiful spacing, font weights, and colors to standard HTML elements (like `<h1>`, `<ul>`, `<code>`) generated from the markdown.
3.  **File Upload Logic**: The `handleFileUpload` function uses the `FileReader` API to read the text content of a local `.md` file and injects it directly into the component's state, allowing the user to review it before saving to Firebase.
4.  **Firebase Integration**: The `handleSave` function checks if an ID exists to determine whether to perform an `updateDoc` (edit) or an `addDoc` (create), ensuring the system handles multiple pages correctly.
5.  **User Experience**: Includes loading states (`isSaving`) and a hidden file input triggered by a styled button for a cleaner UI.

To build a robust multi-page documentation system in Next.js, we must combine a dynamic sidebar for navigation with a centralized state that manages the "active" document. 

Below is the detailed explanation and implementation.

### 1. The Importance of the `"use client"` Directive

In the Next.js App Router architecture, components are **Server Components** by default. Server Components are rendered on the server to improve performance and SEO, but they have limitations:
*   **No State or Effects**: You cannot use `useState` or `useEffect` because the server doesn't maintain a persistent state for the user's browser session.
*   **No Browser APIs**: You cannot access the `window` object, `localStorage`, or handle browser events like `onClick`.
*   **No Real-time Listeners**: Firebase's `onSnapshot` requires a persistent connection from the client's browser to the database.

By adding `"use client"` at the very top of the file, you instruct Next.js to treat this component (and its imports) as a **Client Component**. This is mandatory for our documentation system because we need to track which page is currently selected, handle text input in the editor, and listen for real-time updates from Firestore.

### 2. Implementing the Multi-Page System

The multi-page functionality is achieved by:
1.  **Firestore Collection**: Storing each documentation page as a separate document in a `docs` collection.
2.  **Sidebar Navigation**: Fetching the list of document titles and IDs to create a navigation menu.
3.  **Active State**: Using a state variable (`activeDoc`) to determine which content to render in the main viewer/editor.

### Implementation

```python
# Note: This is JavaScript/TypeScript code for a Next.js application, 
# formatted in a Python block as requested.

"use client";

import React, { useState, useEffect } from 'react';
import { db } from "@/lib/firebase";
import { 
  collection, 
  addDoc, 
  doc, 
  updateDoc, 
  onSnapshot, 
  query, 
  orderBy,
  serverTimestamp 
} from "firebase/firestore";

// MarkdownRX components for professional editing and rendering
import { MarkdownEditor, MarkdownRenderer } from 'markdownrx'; 

/**
 * DocumentationSystem
 * A multi-page management interface for documentation.
 */
export default function DocumentationSystem() {
  // --- State Management (Requires "use client") ---
  const [documents, setDocuments] = useState([]);
  const [activeDoc, setActiveDoc] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState("");
  const [loading, setLoading] = useState(true);

  // 1. Fetch all documentation pages from Firebase
  useEffect(() => {
    // It is vital to ensure @/lib/firebase is correctly configured
    const q = query(collection(db, "docs"), orderBy("createdAt", "asc"));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const docsData = snapshot.docs.map(d => ({
        id: d.id,
        ...d.data()
      }));
      setDocuments(docsData);

      // Auto-select the first document if none is active
      if (docsData.length > 0 && !activeDoc) {
        setActiveDoc(docsData[0]);
        setEditContent(docsData[0].content);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [activeDoc]);

  // 2. Create a new documentation page
  const handleCreateNew = async () => {
    const title = prompt("Enter document title:");
    if (!title) return;

    const newDoc = {
      title,
      content: `# ${title}\n\nNew documentation content starts here...`,
      createdAt: serverTimestamp(),
    };

    const docRef = await addDoc(collection(db, "docs"), newDoc);
    // Switch to the new document immediately
    setActiveDoc({ id: docRef.id, ...newDoc });
    setEditContent(newDoc.content);
    setIsEditing(true);
  };

  // 3. Save changes to Firestore
  const handleSave = async () => {
    if (!activeDoc) return;
    try {
      const docRef = doc(db, "docs", activeDoc.id);
      await updateDoc(docRef, {
        content: editContent,
        lastUpdated: serverTimestamp(),
      });
      setIsEditing(false);
    } catch (error) {
      console.error("Error updating document:", error);
      alert("Failed to save changes.");
    }
  };

  if (loading) return <div className="p-10 text-center">Loading System...</div>;

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900">
      {/* SIDEBAR: Multi-page Navigation */}
      <aside className="w-64 bg-white border-r border-slate-200 flex flex-col">
        <div className="p-4 border-b border-slate-200 flex justify-between items-center">
          <h2 className="font-bold text-lg">Docs</h2>
          <button 
            onClick={handleCreateNew}
            className="p-1 bg-indigo-600 text-white rounded hover:bg-indigo-700 transition"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        <nav className="flex-1 overflow-y-auto p-2 space-y-1">
          {documents.map((doc) => (
            <button
              key={doc.id}
              onClick={() => { 
                setActiveDoc(doc); 
                setEditContent(doc.content);
                setIsEditing(false); 
              }}
              className={`w-full text-left px-3 py-2 rounded-md text-sm transition ${
                activeDoc?.id === doc.id 
                ? 'bg-indigo-50 text-indigo-700 font-semibold' 
                : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {doc.title}
            </button>
          ))}
        </nav>
      </aside>

      {/* MAIN CONTENT: Editor and Renderer */}
      <main className="flex-1 flex flex-col overflow-hidden bg-white">
        {activeDoc ? (
          <>
            <header className="h-16 border-b border-slate-200 px-8 flex justify-between items-center">
              <h1 className="text-xl font-semibold">{activeDoc.title}</h1>
              <div className="flex gap-2">
                {isEditing ? (
                  <>
                    <button onClick={() => setIsEditing(false)} className="px-4 py-2 text-sm text-slate-600">Cancel</button>
                    <button onClick={handleSave} className="px-4 py-2 text-sm bg-indigo-600 text-white rounded-md shadow-sm">Save</button>
                  </>
                ) : (
                  <button onClick={() => setIsEditing(true)} className="px-4 py-2 text-sm border border-slate-300 rounded-md hover:bg-slate-50">Edit Page</button>
                )}
              </div>
            </header>

            <div className="flex-1 overflow-y-auto p-8">
              <div className="max-w-4xl mx-auto">
                {isEditing ? (
                  <div className="border rounded-lg overflow-hidden shadow-sm">
                    <MarkdownEditor
                      value={editContent}
                      onChange={(val) => setEditContent(val)}
                      minHeight="600px"
                    />
                  </div>
                ) : (
                  /* 'prose' class from @tailwindcss/typography ensures proper formatting */
                  <article className="prose prose-slate max-w-none">
                    <MarkdownRenderer content={activeDoc.content} />
                  </article>
                )}
              </div>
            </div>
          </>
        ) : (
          <div className="flex items-center justify-center h-full text-slate-400">
            Select a document to begin.
          </div>
        )}
      </main>
    </div>
  );
}
