template <typename T>
class MuseumManager {
private:
    // 8. STL LIBRARY: Using vector to store pointers (Polymorphism)
    std::vector<T*> collection;

public:
    ~MuseumManager() {
        for (auto item : collection) delete item;
    }

    // 6. METHOD OVERLOADING: Add item normally
    void addExhibit(T* item) {
        collection.push_back(item);
    }

    // 6. METHOD OVERLOADING: Add item with priority (to the front)
    void addExhibit(T* item, bool priority) {
