### 2. Python Script for Raspberry Pi (Secure Listener)

On the Raspberry Pi, instead of allowing raw shell commands (which is a security risk), you should use a script that listens for specific "action keys" and executes predefined functions.

```python
import socket
import subprocess

def start_server():
    # Define the Pi's IP and a custom port
    host = '0.0.0.0' 
    port = 5000 

    # Create a socket object
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.bind((host, port))
    server_socket.listen(5)

    print(f"Listening on {host}:{port}...")

    while True:
        client_socket, addr = server_socket.accept()
        print(f"Connection from {addr}")

        data = client_socket.recv(1024).decode('utf-8').strip()

        # Security: Use a mapping instead of executing raw strings
        commands = {
            "MOVE_UP": "/usr/bin/python3 /home/pi/scripts/up.py",
            "MOVE_DOWN": "/usr/bin/python3 /home/pi/scripts/down.py"
        }

        if data in commands:
            print(f"Executing: {data}")
            subprocess.run(commands[data].split())
            client_socket.send("SUCCESS".encode())
        else:
            print(f"Invalid command received: {data}")
            client_socket.send("INVALID_COMMAND".encode())

        client_socket.close()

if __name__ == "__main__":
    start_server()
```

