import React, { useState, useEffect, useRef } from 'react';
import { 
  StyleSheet, 
  View, 
  Dimensions, 
  Text, 
  PanResponder, 
  ActivityIndicator, 
  TouchableOpacity,
  Alert
} from 'react-native';
import Svg, { Path, Circle, Text as SvgText, G } from 'react-native-svg';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');
const PADDING = 50;
const COORDINATE_MAX = 2160;

// Calculate the size of the drawing area based on screen dimensions
const CANVAS_SIZE = Math.min(SCREEN_WIDTH, SCREEN_HEIGHT) - PADDING * 2;

const App = () => {
  const [allPoints, setAllPoints] = useState([]);
  const [batchIndex, setBatchIndex] = useState(0);
  const [nextPointToHit, setNextPointToHit] = useState(0);
  const [completedPaths, setCompletedPaths] = useState([]);
  const [currentPath, setCurrentPath] = useState('');
  const [isFinished, setIsFinished] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // 1. API Call with Error Handling
  const fetchPoints = async () => {
    setIsLoading(true);
    setError(null);
    try {
      // Replace this URL with your actual API endpoint
      // const response = await fetch('https://api.example.com/points');
      // const data = await response.json();

      // Mocking API response for demonstration
      await new Promise(resolve => setTimeout(resolve, 1000));
      const mockData = Array.from({ length: 30 }, () => ({
        x: Math.floor(Math.random() * COORDINATE_MAX),
        y: Math.floor(Math.random() * COORDINATE_MAX),
      }));

      if (!Array.isArray(mockData)) throw new Error("Data format is not an array");

      setAllPoints(mockData);
    } catch (err) {
      setError("Failed to load points. Please check your connection.");
      Alert.alert("Error", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchPoints();
  }, []);

  // 2. Coordinate Scaling Logic
  const scale = (val) => (val / COORDINATE_MAX) * CANVAS_SIZE + PADDING;

  // Determine which 10 points to show
  const currentBatch = allPoints.slice(batchIndex * 10, (batchIndex + 1) * 10);

  // 3. User Interaction (Drawing & Point Detection)
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt) => {
        const { locationX, locationY } = evt.nativeEvent;
        setCurrentPath(`M${locationX},${locationY}`);
      },
      onPanResponderMove: (evt) => {
        const { locationX, locationY } = evt.nativeEvent;
        setCurrentPath((prev) => `${prev} L${locationX},${locationY}`);

        // Check if user is touching the next point in the sequence
        if (!isFinished && currentBatch.length > 0 && nextPointToHit < currentBatch.length) {
          const target = currentBatch[nextPointToHit];
          const sx = scale(target.x);
          const sy = scale(target.y);

          const distance = Math.sqrt(Math.pow(locationX - sx, 2) + Math.pow(locationY - sy, 2));

          if (distance < 30) { // 30px sensitivity radius
            const nextIdx = nextPointToHit + 1;
            setNextPointToHit(nextIdx);

            // If batch of 10 is finished
            if (nextIdx === 10 || nextIdx === currentBatch.length) {
              handleTransition();
            }
          }
        }
      },
      onPanResponderRelease: () => {
        if (currentPath) {
          setCompletedPaths((prev) => [...prev, currentPath]);
          setCurrentPath('');
        }
      },
    })
  ).current;

  const handleTransition = () => {
    const nextBatchStart = (batchIndex + 1) * 10;
    if (nextBatchStart < allPoints.length) {
      // Move to next batch: This effectively erases old points
      setBatchIndex(batchIndex + 1);
      setNextPointToHit(0);
    } else {
      // No more points: Erase all points and keep only curves
      setIsFinished(true);
    }
  };

  if (isLoading) return <View style={styles.center}><ActivityIndicator size="large" /></View>;
  if (error) return (
    <View style={styles.center}>
      <Text>{error}</Text>
      <TouchableOpacity onPress={fetchPoints} style={styles.button}><Text>Retry</Text></TouchableOpacity>
    </View>
  );

  return (
    <View style={styles.container}>
      <Text style={styles.header}>
        {isFinished ? "All Points Connected!" : `Batch ${batchIndex + 1} - Connect Point ${nextPointToHit + 1}`}
      </Text>

      <View {...panResponder.panHandlers} style={styles.canvas}>
        <Svg width="100%" height="100%">
          {/* Retain all previous user drawings */}
          {completedPaths.map((path, i) => (
            <Path key={i} d={path} stroke="black" strokeWidth="2" fill="none" />
          ))}

          {/* Current active drawing line */}
          {currentPath ? <Path d={currentPath} stroke="blue" strokeWidth="2" fill="none" /> : null}

          {/* Render points only if not finished. 
              When batchIndex changes, this list updates, erasing previous points. */}
          {!isFinished && currentBatch.map((pt, index) => {
            const sx = scale(pt.x);
            const sy = scale(pt.y);
            const isActive = index === nextPointToHit;
            const isDone = index < nextPointToHit;

            return (
              <G key={`pt-${batchIndex}-${index}`}>
                <Circle 
                  cx={sx} cy={sy} r={isActive ? 15 : 10} 
                  fill={isDone ? "#4CAF50" : (isActive ? "#2196F3" : "#F44336")} 
                />
                <SvgText x={sx} y={sy + 5} fontSize="10" fill="white" textAnchor="middle" fontWeight="bold">
                  {index + 1}
                </SvgText>
              </G>
            );
          })}
        </Svg>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#fff' },
  center: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  header: { marginTop: 60, textAlign: 'center', fontSize: 18, fontWeight: 'bold' },
  canvas: { flex: 1, marginTop: 20, backgroundColor: '#fafafa' },
  button: { marginTop: 20, padding: 10, backgroundColor: '#ddd', borderRadius: 5 }
});

export default App;
```

### Key Logic Explanations:

1.  **Point Erasure**: The points are rendered using `currentBatch.map(...)`. Because `currentBatch` is a slice of the `allPoints` array based on the `batchIndex`, as soon as `setBatchIndex` is called, the component re-renders with a completely new set of 10 points. The old ones are no longer in the `currentBatch` array and thus disappear from the SVG.
2.  **Curve Retention**: The user's finger movements are converted into SVG Path strings. When a user lifts their finger (`onPanResponderRelease`), the `currentPath` is pushed into the `completedPaths` array. This array is never cleared, ensuring all drawings remain visible throughout the session.
3.  **Final State**: When `isFinished` is set to `true`, the conditional rendering `{!isFinished && ...}` evaluates to false, removing the final set of points while leaving the `completedPaths` intact.
4.  **Scaling**: The `scale` function ensures that the 0-2160 coordinate system fits perfectly within the device's screen width (minus padding), maintaining the aspect ratio.

