To calculate the minor of a matrix efficiently for any size $N \times N$, we use **Gaussian Elimination with Partial Pivoting** to find the determinant of the submatrix. This reduces the complexity from $O(N!)$ (Laplace expansion) to $O(N^3)$, making it suitable for larger matrices.

The following implementation includes a `Matrix` class, error handling, and the logic for submatrix extraction and determinant calculation.

```python
#include <iostream>
#include <vector>
#include <stdexcept>
#include <cmath>
#include <algorithm>

/**
 * A robust C++ implementation for calculating matrix minors.
 * Uses Gaussian Elimination for determinant calculation to ensure O(N^3) performance.
 */

class Matrix {
public:
    size_t rows, cols;
    std::vector<std::vector<double>> data;

    Matrix(size_t r, size_t c) : rows(r), cols(c), data(r, std::vector<double>(c, 0.0)) {}

    // Helper to create a matrix from initializer list
    Matrix(std::initializer_list<std::vector<double>> list) : data(list) {
        rows = data.size();
        cols = rows > 0 ? data[0].size() : 0;
    }

    /**
     * Extracts the submatrix by removing specified row and column.
     */
    Matrix getSubmatrix(size_t rowToRemove, size_t colToRemove) const {
        if (rows <= 1 || cols <= 1) {
            throw std::invalid_argument("Cannot get submatrix of a matrix smaller than 2x2.");
        }

        Matrix sub(rows - 1, cols - 1);
        size_t subRow = 0;
        for (size_t i = 0; i < rows; ++i) {
            if (i == rowToRemove) continue;
            size_t subCol = 0;
            for (size_t j = 0; j < cols; ++j) {
                if (j == colToRemove) continue;
                sub.data[subRow][subCol] = data[i][j];
                subCol++;
            }
            subRow++;
        }
        return sub;
    }

    /**
     * Calculates the determinant using Gaussian Elimination with Partial Pivoting.
     * Complexity: O(N^3)
     */
    double determinant() const {
        if (rows != cols) {
            throw std::domain_error("Determinant requires a square matrix.");
        }

        size_t n = rows;
        if (n == 1) return data[0][0];
        if (n == 2) return data[0][0] * data[1][1] - data[0][1] * data[1][0];

        // Create a copy for elimination
        std::vector<std::vector<double>> temp = data;
        double det = 1.0;

        for (size_t i = 0; i < n; ++i) {
            // Pivot selection (Partial Pivoting)
            size_t pivot = i;
            for (size_t j = i + 1; j < n; ++j) {
                if (std::abs(temp[j][i]) > std::abs(temp[pivot][i])) {
                    pivot = j;
                }
            }

            // Swap rows
            if (pivot != i) {
                std::swap(temp[i], temp[pivot]);
                det *= -1;
            }

            // Check for singularity
            if (std::abs(temp[i][i]) < 1e-12) {
                return 0.0;
            }

            det *= temp[i][i];

            // Elimination
            for (size_t j = i + 1; j < n; ++j) {
                double factor = temp[j][i] / temp[i][i];
                for (size_t k = i + 1; k < n; ++k) {
                    temp[j][k] -= factor * temp[i][k];
                }
            }
        }

        return det;
    }
};

/**
 * The Minor M(i, j) is the determinant of the submatrix 
 * formed by deleting row i and column j.
 */
double calculateMinor(const Matrix& mat, size_t row, size_t col) {
    if (row >= mat.rows || col >= mat.cols) {
        throw std::out_of_range("Index out of matrix bounds.");
    }
    Matrix sub = mat.getSubmatrix(row, col);
    return sub.determinant();
}

