3.  **Numerical Stability**: The Gaussian elimination uses a small epsilon (`1e-15`) to check for near-zero pivots, preventing division-by-zero errors and handling singular matrices gracefully.
4.  **Robust Error Handling**:
    *   Checks if the matrix is square during construction.
    *   Throws `std::out_of_range` for invalid indices.
    *   Throws `std::invalid_argument` if a minor is requested for a $1 \times 1$ matrix (where a minor is mathematically undefined).

To optimize for small matrices (like $3 \times 3$ or $4 \times 4$), using **Recursive Laplace Expansion** is often more efficient than Gaussian Elimination. While Gaussian Elimination has a better asymptotic complexity ($O(N^3)$), the overhead of partial pivoting, row swapping, and floating-point divisions makes it slower for very small dimensions. Laplace expansion for small $N$ avoids these overheads and can be heavily optimized by the compiler.

Below is the C++ implementation. It uses a **Hybrid Approach**:
1.  **For $N \le 3$**: It uses direct algebraic formulas or recursive expansion.
2.  **For $N > 3$**: It falls back to Gaussian Elimination to maintain performance for larger matrices.
3.  **Special Case**: It includes the $O(1)$ optimization for $2 \times 2$ minors (returning the "opposite" element).

### Optimized C++ Implementation

```python
#include <iostream>
#include <vector>
#include <stdexcept>
#include <cmath>
#include <algorithm>

class Matrix {
public:
    size_t rows, cols;
    std::vector<std::vector<double>> data;

    Matrix(size_t r, size_t c) : rows(r), cols(c), data(r, std::vector<double>(c, 0.0)) {}

    Matrix(std::initializer_list<std::vector<double>> list) : data(list) {
        rows = data.size();
        cols = rows > 0 ? data[0].size() : 0;
    }

    /**
     * Extracts a submatrix by removing specified row and column.
     */
    Matrix getSubmatrix(size_t rowToRemove, size_t colToRemove) const {
        Matrix sub(rows - 1, cols - 1);
        size_t si = 0;
        for (size_t i = 0; i < rows; ++i) {
            if (i == rowToRemove) continue;
            size_t sj = 0;
            for (size_t j = 0; j < cols; ++j) {
                if (j == colToRemove) continue;
                sub.data[si][sj] = data[i][j];
                sj++;
            }
            si++;
        }
        return sub;
    }

    /**
     * Determinant using Recursive Laplace Expansion.
     * Optimized for small matrices (N <= 3).
     */
    double determinantRecursive() const {
        if (rows == 1) return data[0][0];
        if (rows == 2) return data[0][0] * data[1][1] - data[0][1] * data[1][0];

        // Direct formula for 3x3 (Rule of Sarrus) to avoid further recursion
        if (rows == 3) {
            return data[0][0] * (data[1][1] * data[2][2] - data[1][2] * data[2][1]) -
                   data[0][1] * (data[1][0] * data[2][2] - data[1][2] * data[2][0]) +
                   data[0][2] * (data[1][0] * data[2][1] - data[1][1] * data[2][0]);
        }

        // General Laplace Expansion for N > 3 (if chosen)
        double det = 0;
        for (size_t j = 0; j < cols; ++j) {
            double sign = (j % 2 == 0) ? 1.0 : -1.0;
            det += sign * data[0][j] * getSubmatrix(0, j).determinantRecursive();
        }
        return det;
    }

    /**
     * Determinant using Gaussian Elimination.
     * Used for larger matrices to maintain O(N^3) complexity.
     */
    double determinantGaussian() const {
        size_t n = rows;
        std::vector<std::vector<double>> temp = data;
        double det = 1.0;
        for (size_t i = 0; i < n; ++i) {
            size_t pivot = i;
            for (size_t j = i + 1; j < n; ++j)
                if (std::abs(temp[j][i]) > std::abs(temp[pivot][i])) pivot = j;

            if (std::abs(temp[pivot][i]) < 1e-15) return 0.0;
            if (pivot != i) { std::swap(temp[i], temp[pivot]); det *= -1; }
            det *= temp[i][i];
            for (size_t j = i + 1; j < n; ++j) {
                double factor = temp[j][i] / temp[i][i];
                for (size_t k = i + 1; k < n; ++k) temp[j][k] -= factor * temp[i][k];
            }
        }
        return det;
    }

    /**
     * Hybrid Determinant Selector
     */
    double determinant() const {
        if (rows != cols) throw std::domain_error("Matrix must be square.");
        // Use Laplace/Direct for small matrices, Gaussian for large
        return (rows <= 3) ? determinantRecursive() : determinantGaussian();
    }
};

/**
 * Optimized Minor Calculation
 */
double calculateMinor(const Matrix& mat, size_t row, size_t col) {
    if (row >= mat.rows || col >= mat.cols) throw std::out_of_range("Index out of bounds.");
    if (mat.rows < 2) throw std::invalid_argument("Minor undefined for matrices < 2x2.");

    // Optimization for 2x2: The minor is just the opposite element.
    // This is the O(1) logic from the original 'minor1' function.
    if (mat.rows == 2) {
        return mat.data[1 - row][1 - col];
    }

    // For 3x3 and larger, extract submatrix and find determinant
    Matrix sub = mat.getSubmatrix(row, col);
    return sub.determinant();
}

int main() {
    try {
        // Test 2x2 (Minor is 1x1 determinant)
        Matrix m2 = {{1, 2}, {3, 4}};
        std::cout << "2x2 Minor M(0,0): " << calculateMinor(m2, 0, 0) << " (Expected: 4)\n";

        // Test 3x3 (Minor is 2x2 determinant)
        // Submatrix for M(1,1) is [[1,3],[7,9]] -> 1*9 - 3*7 = -12
        Matrix m3 = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        std::cout << "3x3 Minor M(1,1): " << calculateMinor(m3, 1, 1) << " (Expected: -12)\n";

        // Test 4x4 (Minor is 3x3 determinant)
        Matrix m4 = {
            {1, 0, 2, -1},
            {3, 0, 0, 5},
            {2, 1, 4, -3},
            {1, 0, 5, 0}
        };
        std::cout << "4x4 Minor M(0,1): " << calculateMinor(m4, 0, 1) << " (Expected: 30)\n";

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
```

### Why this is optimized for small matrices:

1.  **Elimination of Branching/Pivoting**: In the `determinantRecursive` function, the $2 \times 2$ and $3 \times 3$ cases use direct arithmetic formulas. Gaussian elimination requires multiple `if` checks for pivoting and loops for row reduction, which are more expensive than a few multiplications and subtractions for small $N$.
2.  **The $2 \times 2$ Shortcut**: The `calculateMinor` function explicitly checks if the matrix is $2 \times 2$. If it is, it returns the "opposite" element immediately. This is the most efficient possible implementation for the user's original use case, as it avoids creating a `Matrix` object for the submatrix entirely.
3.  **Memory Locality**: For small matrices, the recursive calls stay within the CPU cache. By hardcoding the $3 \times 3$ determinant (Rule of Sarrus), we stop the recursion early, reducing stack frame overhead.
4.  **Hybrid Logic**: By keeping the Gaussian Elimination for $N > 3$, we ensure that the code doesn't hit the $O(N!)$ "wall" if a user accidentally passes a $15 \times 15$ matrix, which would happen with a purely recursive Laplace implementation.

### Evaluation of original functions:
*   **`minor1`**: Was a clever $O(1)$ optimization for $2 \times 2$ matrices, but lacked bounds checking and generality.
*   **`minor2`**: Was incorrect because it attempted to sum multiple $2 \times 2$ determinants in a way that doesn't represent a minor or a standard determinant.

To solve this problem in MATLAB, we will define the function, its gradient, and its Hessian. We will then implement a solver for the trust-region subproblem:
$$\min_{\mathbf{p}} m_k(\mathbf{p}) \quad \text{s.t. } \|\mathbf{p}\| \leq \Delta$$
where $m_k(\mathbf{p}) = f_k + \mathbf{g}_k^T \mathbf{p} + \frac{1}{2} \mathbf{p}^T \mathbf{B}_k \mathbf{p}$.

The solution $\mathbf{p}^*$ is either the Newton step (if the Hessian is positive definite and the step is within the radius) or lies on the boundary $\|\mathbf{p}\| = \Delta$.

Here is the MATLAB implementation:

```python
% MATLAB Script to solve and visualize Trust Region Subproblems
clear; clc; close all;

% Define the points to evaluate
points = [0, -1; 0, 0.5];
point_labels = {'Positive Definite Hessian', 'Indefinite Hessian'};

for i = 1:size(points, 1)
    x_k = points(i, :)';
    [f_k, g_k, B_k] = get_f_grad_hess(x_k);

    % 1. Solve the trust region subproblem for delta from 0 to 2
    deltas = linspace(0, 2, 100);
    p_path = zeros(2, length(deltas));

    for j = 1:length(deltas)
        p_path(:, j) = solve_trust_region(g_k, B_k, deltas(j));
    end

    % 2. Visualization
    figure('Position', [100, 100, 800, 600]);
    hold on; grid on; axis equal;

    % Create grid for contour plot of the quadratic model m_k(p)
    [P1, P2] = meshgrid(linspace(-2.2, 2.2, 100), linspace(-2.2, 2.2, 100));
    M = f_k + g_k(1)*P1 + g_k(2)*P2 + ...
        0.5 * (B_k(1,1)*P1.^2 + 2*B_k(1,2)*P1.*P2 + B_k(2,2)*P2.^2);

    % Plot contours
    [C, h] = contour(P1, P2, M, 20, 'LineWidth', 1);
    clabel(C, h);

    % Plot the solution path p*(delta)
    plot(p_path(1, :), p_path(2, :), 'r-o', 'MarkerSize', 3, 'MarkerFaceColor', 'r', ...
        'DisplayName', 'Solution Path $p^*(\Delta)$');

    % Plot the trust region boundary for Delta = 2
    theta = linspace(0, 2*pi, 100);
    plot(2*cos(theta), 2*sin(theta), 'k--', 'LineWidth', 1.5, 'DisplayName', '\Delta = 2.0');

    % Formatting
    title(sprintf('%s at $x = [0, %.1f]^T$', point_labels{i}, x_k(2)), 'Interpreter', 'latex');
    xlabel('$p_1$', 'Interpreter', 'latex');
    ylabel('$p_2$', 'Interpreter', 'latex');
    legend('Location', 'northeast', 'Interpreter', 'latex');
    ax = gca; ax.XAxisLocation = 'origin'; ax.YAxisLocation = 'origin';
end

%% Helper Functions

function [f, g, B] = get_f_grad_hess(x)
    % f(x) = 10(x2 - x1^2)^2 + (1 - x1)^2
    x1 = x(1); x2 = x(2);
    f = 10 * (x2 - x1^2)^2 + (1 - x1)^2;
    g = [-40 * x1 * (x2 - x1^2) - 2 * (1 - x1); 
          20 * (x2 - x1^2)];
    B = [120 * x1^2 - 40 * x2 + 2, -40 * x1; 
         -40 * x1, 20];
end

function p = solve_trust_region(g, B, delta)
    if delta < 1e-7
        p = [0; 0]; return;
    end

    eigvals = eig(B);
    lambda_min = min(eigvals);

    % Check if Newton step is valid (B is PD and step is within delta)
    if lambda_min > 0
        p_n = -B \ g;
        if norm(p_n) <= delta
            p = p_n; return;
        end
    end

    % Otherwise, solution lies on the boundary ||p|| = delta
    % Solve ||(B + lambda*I)^-1 * g|| = delta for lambda
    % We need B + lambda*I to be positive semi-definite
    lambda_lower = max(0, -lambda_min + 1e-4);

    % Objective function for lambda: norm(p(lambda)) - delta = 0
    phi = @(lam) norm((B + lam * eye(2)) \ (-g)) - delta;

    % Find lambda using fzero
    try
        % Search for lambda in a reasonable range
        options = optimset('Display', 'off');
        lam_star = fzero(phi, [lambda_lower, lambda_lower + 500], options);
        p = (B + lam_star * eye(2)) \ (-g);
    catch
        % Fallback for hard cases (e.g., g is orthogonal to eigenvector of lambda_min)
        p = (B + lambda_lower * eye(2)) \ (-g);
        p = p * (delta / norm(p));
    end
end
```

### Key Observations from the MATLAB Output:

1.  **At $x = [0, -1]^T$ (Positive Definite):**
    *   The Hessian is $B = \begin{bmatrix} 42 & 0 \\ 0 & 20 \end{bmatrix}$.
    *   The Newton step is $\mathbf{p}^N \approx [0.047, 1.0]^T$, with a norm slightly greater than 1.
    *   As $\Delta$ increases from 0 to $\approx 1.001$, the solution path moves along the boundary. Once $\Delta$ exceeds the norm of the Newton step, the solution stays at the unconstrained minimum of the quadratic model.

2.  **At $x = [0, 0.5]^T$ (Indefinite):**
    *   The Hessian is $B = \begin{bmatrix} -18 & 0 \\ 0 & 20 \end{bmatrix}$.
    *   Because there is a negative eigenvalue ($-18$), the quadratic model is not bounded below.
    *   The solution $\mathbf{p}^*$ will **always** lie on the boundary $\|\mathbf{p}\| = \Delta$ for all $\Delta > 0$. The path shows the trajectory of the constrained minimizer as the trust region expands.

