  if (!req.file) return res.status(400).json({ error: "No file uploaded" });

  // Add job to the background queue
  await csvQueue.add('process-csv', { 
    filePath: req.file.path,
    originalName: req.file.originalname 
  });

  // Return immediate response to prevent timeout
  return res.status(202).json({
    message: "File accepted. Processing started in the background.",
    jobId: "Check email for completion status."
  });
});

// --- 4. Background Worker (The Consumer) ---
// This runs separately from the main thread to handle the queue.
const worker = new Worker('csv-processing', async (job) => {
  const { filePath } = job.data;

  return new Promise((resolve, reject) => {
    // --- 5. Multiprocessing (Worker Threads) ---
    // We spawn a separate thread to handle the heavy parsing and DB insertion.
    const thread = new ThreadWorker(`
      const { parentPort, workerData } = require('worker_threads');
      const Papa = require('papaparse');
      const fs = require('fs');
      const { Sequelize, DataTypes } = require('sequelize');

      async function run() {
        const sequelize = new Sequelize('postgres://user:pass@localhost:5432/db');
        const Customer = sequelize.define('Customer', {
          name: DataTypes.STRING,
          email: DataTypes.STRING
        });

        let count = 0;
        const fileStream = fs.createReadStream(workerData.path);

        // Papa Parse with streaming for memory efficiency
        Papa.parse(fileStream, {
          header: true,
          chunkSize: 1024 * 1024 * 10, // 10MB chunks
          chunk: async (results, parser) => {
            parser.pause(); // Pause stream to handle DB backpressure
            try {
              await Customer.bulkCreate(results.data); // Optimized Bulk Insert
              count += results.data.length;
              parser.resume();
            } catch (err) {
              console.error(err);
            }
          },
          complete: () => {
            parentPort.postMessage(count);
            fs.unlinkSync(workerData.path); // Cleanup
          }
        });
      }
      run();
    `, { 
      eval: true, 
      workerData: { path: filePath } 
    });

    thread.on('message', async (totalRows) => {
      await sendEmail(totalRows);
      resolve();
    });
    thread.on('error', reject);
  });
}, { connection });

app.listen(3000, () => console.log('Server running on port 3000'));
