import os
import collections

def verify_and_count_exons(gff_path):
    # 1. Verify File Path
    if not os.path.exists(gff_path):
        print(f"Error: File not found at {gff_path}")
        return

    # 2. Verify GFF3 Format (Check header)
    with open(gff_path, 'r') as f:
        first_line = f.readline()
        if not first_line.startswith('##gff-version 3'):
            print("Warning: File does not have a standard GFF3 header.")

    # Data structures
    transcript_to_gene = {}
    gene_exon_counts = collections.defaultdict(int)

    # 3. Process File
    with open(gff_path, 'r') as f:
        for line in f:
            if line.startswith('#') or not line.strip():
                continue

            cols = line.strip().split('\t')
            if len(cols) < 9:
                continue

            feature_type = cols[2]
            attributes = cols[8]

            # Parse attributes into a dictionary
            attr_dict = {}
            for item in attributes.split(';'):
                if '=' in item:
                    k, v = item.split('=', 1)
                    attr_dict[k] = v

            # Step A: Map Transcripts to Genes
            if feature_type in ['mRNA', 'transcript', 'transcript_gene_segment']:
                t_id = attr_dict.get('ID')
                p_id = attr_dict.get('Parent')
                if t_id and p_id:
                    # Remove prefixes like 'transcript:' or 'gene:'
                    clean_t = t_id.split(':')[-1]
                    clean_g = p_id.split(':')[-1]
                    transcript_to_gene[clean_t] = clean_g

            # Step B: Count Exons
            elif feature_type == 'exon':
                p_id = attr_dict.get('Parent')
                if p_id:
                    clean_p = p_id.split(':')[-1]
                    # If the parent is a transcript we mapped, use the gene ID
                    # Otherwise, assume the parent is the gene ID (flat GFF)
                    gene_id = transcript_to_gene.get(clean_p, clean_p)
                    gene_exon_counts[gene_id] += 1

    # 4. Output Results
    if not gene_exon_counts:
        print("No exons found. Check if the feature type in column 3 is exactly 'exon'.")
    else:
        for gene, count in sorted(gene_exon_counts.items()):
            print(f"Gene: {gene}, Exon Count: {count}")

# Execution
