% 2. Define the coordinates that were corrupted
% The original indices were (10,10), (10,11), (11,10), (11,11)
corrupted_coords = [10,10; 10,11; 11,10; 11,11];

% 3. Restore the values
% Since the degradation was an addition of a massive constant (nn), 
% the original signal at those points is buried. We can estimate the 
% original values by averaging the surrounding 8 neighbors (interpolation).
[M, N] = size(y);
Y_restored = Y;

for i = 1:size(corrupted_coords, 1)
    r = corrupted_coords(i, 1);
    c = corrupted_coords(i, 2);

    % Interpolate the primary corrupted points
    % We take the average of the immediate neighbors
    neighbor_avg = (Y(r-1, c) + Y(r+1, c) + Y(r, c-1) + Y(r, c+1)) / 4;
    Y_restored(r, c) = neighbor_avg;

    % Because real(ifft2(x)) was used, the spikes are mirrored 
    % at the conjugate symmetric locations. We must clean those too.
    % MATLAB index formula for conjugate symmetry:
    r_sym = mod(M - (r - 1), M) + 1;
    c_sym = mod(N - (c - 1), N) + 1;

    neighbor_avg_sym = (Y(r_sym-1, c_sym) + Y(r_sym+1, c_sym) + ...
                        Y(r_sym, c_sym-1) + Y(r_sym, c_sym+1)) / 4;
    Y_restored(r_sym, c_sym) = neighbor_avg_sym;
end

% 4. Inverse FFT to get the restored image
im_restored = real(ifft2(Y_restored));

% 5. Display results
