// Forward declaration to allow Synapse to reference the Neuron class
class IzhikevichNeuron;

/**
 * @brief Represents a synaptic connection between neurons.
 * Includes STDP (Spike-Timing-Dependent Plasticity) logic.
 */
struct Synapse {
    IzhikevichNeuron* target;
    double weight;
    double last_pre_spike_time;

    // STDP Parameters
    const double learning_rate = 0.05;
    const double tau_stdp = 20.0; // ms
    const double max_weight = 5.0;
    const double min_weight = 0.0;

    Synapse(IzhikevichNeuron* target_node, double initial_weight)
        : target(target_node), weight(initial_weight), last_pre_spike_time(-1000.0) {}

    /**
     * @brief Adjusts weight based on the timing between pre- and post-synaptic spikes.
     * @param t Current simulation time
     * @param last_post_spike_time The last time the target neuron fired
     * @param is_pre_spike True if the trigger is a pre-synaptic spike
     */
    void update_stdp(double t, double last_post_spike_time, bool is_pre_spike) {
        double dt;
        if (is_pre_spike) {
            last_pre_spike_time = t;
            dt = last_pre_spike_time - last_post_spike_time;
            // LTD: Pre-synaptic spike occurs after post-synaptic spike
            if (dt > 0) {
                weight -= learning_rate * std::exp(-std::abs(dt) / tau_stdp);
            }
        } else {
            dt = t - last_pre_spike_time;
            // LTP: Post-synaptic spike occurs after pre-synaptic spike
            if (dt > 0) {
                weight += learning_rate * std::exp(-std::abs(dt) / tau_stdp);
            }
        }
        // Clamp weight to biological bounds
        weight = std::max(min_weight, std::min(max_weight, weight));
    }
};

/**
 * @brief Implementation of the Izhikevich Neuron Model.
 * Equations:
 * v' = 0.04v^2 + 5v + 140 - u + I
 * u' = a(bv - u)
 * if v >= 30mV, then v = c, u = u + d
 */
class IzhikevichNeuron {
private:
    // Model Parameters
    double a, b, c, d;
    // State Variables
    double v, u;
    double input_current;
    double last_spike_time;

    // Connectivity: Map target pointer to Synapse object for O(1) access
    std::unordered_map<IzhikevichNeuron*, std::shared_ptr<Synapse>> outbound_synapses;
    // Keep track of who connects to us to trigger post-synaptic STDP updates
    std::vector<Synapse*> inbound_synapses;

public:
    IzhikevichNeuron(double a = 0.02, double b = 0.2, double c = -65.0, double d = 8.0)
        : a(a), b(b), c(c), d(d), v(c), u(b * c), input_current(0.0), last_spike_time(-1000.0) {}

    /**
     * @brief Connects this neuron to a target neuron.
     */
    void connect_to(IzhikevichNeuron* target, double weight = 1.0) {
        if (!target) throw std::invalid_argument("Target neuron cannot be null.");
        if (target == this) throw std::invalid_argument("Self-loops are not supported in this simple model.");

        auto synapse = std::make_shared<Synapse>(target, weight);
        outbound_synapses[target] = synapse;
        target->register_inbound(synapse.get());
    }

    /**
     * @brief Disconnects this neuron from a target neuron.
     */
    void disconnect_from(IzhikevichNeuron* target) {
        if (outbound_synapses.erase(target)) {
            target->unregister_inbound_from(this);
        }
    }

    void receive_input(double current) {
        input_current += current;
    }

    /**
     * @brief Advances the neuron state by one time step dt.
     * @return true if the neuron fired a spike.
     */
    bool step(double t, double dt = 1.0) {
        bool fired = false;

        // Euler integration of Izhikevich equations
        v += dt * (0.04 * v * v + 5.0 * v + 140.0 - u + input_current);
        u += dt * (a * (b * v - u));

        // Reset input for the next step
        input_current = 0.0;

        if (v >= 30.0) {
            fired = true;
            v = c;
            u += d;
            last_spike_time = t;

            // 1. Notify outbound synapses (Pre-synaptic spike event)
            for (auto& pair : outbound_synapses) {
                Synapse* s = pair.second.get();
                s->update_stdp(t, s->target->get_last_spike_time(), true);
                // Propagate signal to target
                s->target->receive_input(s->weight * 15.0); // 15.0 is a scaling factor
            }

            // 2. Notify inbound synapses (Post-synaptic spike event)
            for (Synapse* s : inbound_synapses) {
                s->update_stdp(t, last_spike_time, false);
            }
        }

        return fired;
    }

    double get_last_spike_time() const { return last_spike_time; }
    double get_v() const { return v; }

protected:
    void register_inbound(Synapse* s) {
        inbound_synapses.push_back(s);
    }

    void unregister_inbound_from(IzhikevichNeuron* source) {
        inbound_synapses.erase(
            std::remove_if(inbound_synapses.begin(), inbound_synapses.end(),
                [&](Synapse* s) { 
