        } else {
            dt = t - last_pre_spike_time;
            // LTP: Post-spike occurs after a pre-spike
            if (dt > 0) weight += learning_rate * std::exp(-std::abs(dt) / tau_stdp);
        }
        weight = std::clamp(weight, 0.0, max_weight);
    }
};

/**
 * @brief Izhikevich Neuron Model Class.
 */
class IzhikevichNeuron {
private:
    // Model Parameters
    double a, b, c, d;
    // State Variables
    double v, u;
    double input_current;
    double last_spike_time;

    // Dynamic Connectivity
    std::unordered_map<IzhikevichNeuron*, std::unique_ptr<Synapse>> outbound;
    std::vector<Synapse*> inbound; // Pointers to synapses where this is the target

public:
    IzhikevichNeuron(double a=0.02, double b=0.2, double c=-65.0, double d=8.0)
        : a(a), b(b), c(c), d(d), v(c), u(b*c), input_current(0.0), last_spike_time(-1000.0) {}

    void connect_to(IzhikevichNeuron* target, double weight = 0.5) {
        if (outbound.find(target) == outbound.end()) {
            auto syn = std::make_unique<Synapse>(target, weight);
            target->register_inbound(syn.get());
            outbound[target] = std::move(syn);
        }
    }

    void disconnect_from(IzhikevichNeuron* target) {
        if (outbound.count(target)) {
            target->unregister_inbound(outbound[target].get());
            outbound.erase(target);
        }
    }

    void receive_input(double current) { input_current += current; }

    bool step(double t, double dt = 1.0) {
        bool fired = false;

        // Izhikevich Equations
        // v' = 0.04v^2 + 5v + 140 - u + I
        // u' = a(bv - u)
        v += dt * (0.04 * v * v + 5.0 * v + 140.0 - u + input_current);
        u += dt * (a * (b * v - u));
        input_current = 0.0; // Reset for next step

        if (v >= 30.0) {
            fired = true;
            v = c;
            u += d;
            last_spike_time = t;

            // Notify outbound (Pre-synaptic event)
            for (auto& [target, syn] : outbound) {
                syn->apply_stdp(t, target->last_spike_time, true);
                target->receive_input(syn->weight * 15.0); // 15.0 is a scaling factor
            }
            // Notify inbound (Post-synaptic event)
            for (auto* syn : inbound) {
                syn->apply_stdp(t, last_spike_time, false);
            }
        }
        return fired;
    }

    double get_v() const { return v; }
    void register_inbound(Synapse* s) { inbound.push_back(s); }
    void unregister_inbound(Synapse* s) {
        inbound.erase(std::remove(inbound.begin(), inbound.end(), s), inbound.end());
    }
};

int main() {
    // Example: Building a simple 2-neuron circuit
    IzhikevichNeuron sensory(0.02, 0.2, -65.0, 8.0);
    IzhikevichNeuron motor(0.02, 0.2, -65.0, 8.0);

    sensory.connect_to(&motor, 0.5);

    std::cout << "Time\tSensory_V\tMotor_V" << std::endl;
    for (int t = 0; t < 100; ++t) {
        sensory.receive_input(10.0); // Stimulate sensory neuron

        bool s_fired = sensory.step(t);
        bool m_fired = motor.step(t);

        if (t % 10 == 0 || s_fired || m_fired) {
            std::cout << t << "\t" << sensory.get_v() << "\t\t" << motor.get_v();
            if (s_fired) std::cout << " [S SPIKE]";
            if (m_fired) std::cout << " [M SPIKE]";
            std::cout << std::endl;
        }
    }
    return 0;
}
