// Forward declaration
class IzhikevichNeuron;

/**
 * @brief Represents a synaptic connection with STDP logic.
 */
struct Synapse {
    IzhikevichNeuron* source;
    IzhikevichNeuron* target;
    double weight;
    double last_pre_spike_time;

    // STDP Parameters
    static constexpr double learning_rate = 0.05;
    static constexpr double tau_stdp = 20.0; // ms decay constant
    static constexpr double max_weight = 5.0;
    static constexpr double min_weight = 0.0;

    Synapse(IzhikevichNeuron* src, IzhikevichNeuron* tgt, double w)
        : source(src), target(tgt), weight(w), last_pre_spike_time(-1000.0) {}

    /**
     * @brief Updates weight based on spike timing.
     * @param t Current simulation time.
     * @param last_post_spike_time Last time the target neuron fired.
     * @param is_pre_spike True if triggered by the source neuron firing.
     */
    void update_stdp(double t, double last_post_spike_time, bool is_pre_spike) {
        double dt;
        if (is_pre_spike) {
            last_pre_spike_time = t;
            dt = last_pre_spike_time - last_post_spike_time;
            // LTD: Pre-synaptic spike occurs shortly after a post-synaptic spike
            if (dt > 0 && dt < 100.0) {
                weight -= learning_rate * std::exp(-std::abs(dt) / tau_stdp);
            }
        } else {
            dt = t - last_pre_spike_time;
            // LTP: Post-synaptic spike occurs shortly after a pre-synaptic spike
            if (dt > 0 && dt < 100.0) {
                weight += learning_rate * std::exp(-std::abs(dt) / tau_stdp);
            }
        }
        weight = std::clamp(weight, min_weight, max_weight);
    }
};

/**
 * @brief Izhikevich Neuron Model.
 * Replicates biological firing patterns using two differential equations.
 */
class IzhikevichNeuron {
private:
    // Model Parameters
    double a, b, c, d;
    // State Variables
    double v, u;
    double input_current;
    double last_spike_time;

    // Connectivity
    // Outbound: We own the synapse objects we originate
    std::unordered_map<IzhikevichNeuron*, std::shared_ptr<Synapse>> outbound;
    // Inbound: We keep weak references to synapses targeting us
    std::vector<std::weak_ptr<Synapse>> inbound;

public:
    /**
     * @param a time scale of recovery variable u
     * @param b sensitivity of u to subthreshold fluctuations of v
     * @param c after-spike reset value of v
     * @param d after-spike reset of u
     */
    IzhikevichNeuron(double a = 0.02, double b = 0.2, double c = -65.0, double d = 8.0)
        : a(a), b(b), c(c), d(d), v(c), u(b * c), input_current(0.0), last_spike_time(-1000.0) {}

    /**
     * @brief Dynamically connects this neuron to a target.
     */
    void connect_to(IzhikevichNeuron* target, double weight = 1.0) {
        if (!target || target == this) return;
        if (outbound.find(target) == outbound.end()) {
            auto syn = std::make_shared<Synapse>(this, target, weight);
            outbound[target] = syn;
            target->register_inbound(syn);
        }
    }

    /**
     * @brief Dynamically removes a connection.
     */
    void disconnect_from(IzhikevichNeuron* target) {
        if (outbound.erase(target)) {
            target->cleanup_inbound();
        }
    }

    void receive_input(double current) {
        input_current += current;
    }

    /**
     * @brief Advances the neuron state by dt (ms).
     */
    bool step(double t, double dt = 1.0) {
        bool fired = false;

        // Izhikevich Equations (Euler Integration)
        // v' = 0.04v^2 + 5v + 140 - u + I
        v += dt * (0.04 * v * v + 5.0 * v + 140.0 - u + input_current);
        // u' = a(bv - u)
        u += dt * (a * (b * v - u));

        input_current = 0.0; // Reset input for next integration step

        if (v >= 30.0) {
            fired = true;
            v = c;
            u += d;
            last_spike_time = t;

            // 1. Pre-synaptic event: Update STDP and propagate signal
            for (auto& [target, syn] : outbound) {
                syn->update_stdp(t, target->last_spike_time, true);
                target->receive_input(syn->weight * 15.0); // 15.0 is a synaptic gain factor
            }

            // 2. Post-synaptic event: Update STDP for all incoming synapses
            for (auto it = inbound.begin(); it != inbound.end(); ) {
                if (auto syn = it->lock()) {
                    syn->update_stdp(t, last_spike_time, false);
                    ++it;
                } else {
                    it = inbound.erase(it); // Clean up expired weak pointers
                }
            }
        }
        return fired;
    }

    double get_v() const { return v; }
    double get_last_spike_time() const { return last_spike_time; }

protected:
    void register_inbound(std::weak_ptr<Synapse> s) {
        inbound.push_back(s);
    }

    void cleanup_inbound() {
        inbound.erase(std::remove_if(inbound.begin(), inbound.end(),
            [](std::weak_ptr<Synapse> s) { return s.expired(); }), inbound.end());
    }
};

