    % This version includes error handling and randomness improvements.

    % 1. Ensure Symbolic Math Toolbox is present
    if ~license('test', 'symbolic_toolbox')
        error('Symbolic Math Toolbox is required for high-precision RSA.');
    end

    % 2. Address Pitfall: Weak Randomness
    % Seed the random number generator using the system clock
    rng('shuffle');

    fprintf('Generating robust keys for %d-bit encryption...\n', bitLength);

    % 3. Generate Primes p and q
    p_bits = floor(bitLength / 2);
    p = generate_secure_prime(p_bits);
    q = generate_secure_prime(p_bits);

    % Ensure p and q are not too close (prevents Fermat Factorization)
    while abs(double(p-q)) < 2^(p_bits - 100)
        q = generate_secure_prime(p_bits);
    end

    n = p * q;
    phi = (p - 1) * (q - 1);

    % 4. Address Pitfall: Coprimality of e and phi
    % We start with 65537 (Fermat prime F4), which is efficient for encryption
    e = sym(65537);
    while gcd(e, phi) ~= 1
        e = e + 2; % Search for the next odd number
    end

    % 5. Address Pitfall: Modular Inverse and Sign
    % [g, d, ~] = gcd(e, phi) solves: e*d + phi*k = g
    [g, d, ~] = gcd(e, phi);

    if g ~= 1
        error('Failed to find a valid modular inverse.');
    end

    % Ensure d is positive
    d = mod(d, phi);

    % Return keys as structures
    publicKey = struct('e', e, 'n', n);
    privateKey = struct('d', d, 'n', n);

    fprintf('Key generation complete.\n');
end

function p = generate_secure_prime(bits)
    % Helper to generate a large symbolic prime
    % We use a string-based approach to bypass double-precision limits
