```python
package main

import (
	"fmt"
	"math/rand"
	"sort"
	"time"
)

// Category defines the investment options
type Category struct {
	Name string
	ROI  float64
}

// Individual represents a potential solution (a set of weights)
type Individual struct {
	Weights []float64
	Fitness float64
}

// BudgetOptimizerGA holds the configuration for the algorithm
type BudgetOptimizerGA struct {
	Categories   []Category
	TotalBudget  float64
	PopSize      int
	MutationRate float64
	Generations  int
}

// NewBudgetOptimizerGA initializes the GA
func NewBudgetOptimizerGA(cats []Category, budget float64) *BudgetOptimizerGA {
	return &BudgetOptimizerGA{
		Categories:   cats,
		TotalBudget:  budget,
		PopSize:      100,
		MutationRate: 0.1,
		Generations:  200,
	}
}

// normalize ensures all weights sum up to the TotalBudget
func (ga *BudgetOptimizerGA) normalize(weights []float64) []float64 {
	sum := 0.0
	for _, w := range weights {
		sum += w
	}
	normalized := make([]float64, len(weights))
	for i, w := range weights {
		normalized[i] = (w / sum) * ga.TotalBudget
	}
	return normalized
}

// createIndividual generates a random set of normalized weights
func (ga *BudgetOptimizerGA) createIndividual() Individual {
	weights := make([]float64, len(ga.Categories))
	for i := range weights {
		weights[i] = rand.Float64()
	}
	ind := Individual{Weights: ga.normalize(weights)}
	ind.Fitness = ga.calculateFitness(ind.Weights)
	return ind
}

// calculateFitness calculates ROI and applies a penalty for constraints
func (ga *BudgetOptimizerGA) calculateFitness(weights []float64) float64 {
	score := 0.0
	penalty := 0.0
	for i, w := range weights {
		score += w * ga.Categories[i].ROI
		// Constraint: No single category should exceed 40% (0.4)
		if w > 0.4 {
			penalty += (w - 0.4) * 100
		}
	}
	return score - penalty
}

// crossover combines two parents to create a child
func (ga *BudgetOptimizerGA) crossover(p1, p2 Individual) Individual {
	point := rand.Intn(len(ga.Categories)-1) + 1
	childWeights := append([]float64{}, p1.Weights[:point]...)
	childWeights = append(childWeights, p2.Weights[point:]...)

	ind := Individual{Weights: ga.normalize(childWeights)}
	ind.Fitness = ga.calculateFitness(ind.Weights)
	return ind
}

// mutate randomly alters one weight in the individual
func (ga *BudgetOptimizerGA) mutate(ind *Individual) {
	if rand.Float64() < ga.MutationRate {
		idx := rand.Intn(len(ga.Categories))
		ind.Weights[idx] = rand.Float64()
		ind.Weights = ga.normalize(ind.Weights)
		ind.Fitness = ga.calculateFitness(ind.Weights)
	}
}

// Run executes the Genetic Algorithm
func (ga *BudgetOptimizerGA) Run() Individual {
	rand.Seed(time.Now().UnixNano())

	// 1. Initialize Population
	population := make([]Individual, ga.PopSize)
	for i := 0; i < ga.PopSize; i++ {
		population[i] = ga.createIndividual()
	}

	for gen := 0; gen < ga.Generations; gen++ {
		// 2. Sort by Fitness (Descending)
		sort.Slice(population, func(i, j int) bool {
			return population[i].Fitness > population[j].Fitness
		})

		// 3. Elitism: Keep the top 10%
		nextGen := make([]Individual, 0, ga.PopSize)
		nextGen = append(nextGen, population[:ga.PopSize/10]...)

		// 4. Fill the rest of the population
		for len(nextGen) < ga.PopSize {
			// Select from top 20 individuals
			p1 := population[rand.Intn(20)]
			p2 := population[rand.Intn(20)]

			child := ga.crossover(p1, p2)
			ga.mutate(&child)
			nextGen.append(nextGen, child)
		}
		population = nextGen
	}

	sort.Slice(population, func(i, j int) bool {
		return population[i].Fitness > population[j].Fitness
	})
	return population[0]
}

func main() {
	investmentCategories := []Category{
		{"Tech Stocks", 0.12},
		{"Bonds", 0.04},
		{"Real Estate", 0.08},
		{"Crypto", 0.25},
		{"Emerging Markets", 0.10},
	}

	optimizer := NewBudgetOptimizerGA(investmentCategories, 1.0)
	best := optimizer.Run()

	fmt.Println("Optimal Budget Allocation:")
	for i, weight := range best.Weights {
		fmt.Printf("%s: %.2f%%\n", investmentCategories[i].Name, weight*100)
	}
	fmt.Printf("Expected Total Return (Adjusted for Penalty): %.4f\n", best.Fitness)
}
```

### Step-by-Step Walkthrough

#### 1. Data Structures
In Go, we define `Category` to hold the ROI data and `Individual` to hold the "chromosome" (the weights) and its calculated fitness. This makes the code more readable than using generic maps or lists.

#### 2. Normalization Logic
The `normalize` function is the most critical part of a weight budgeting GA. Since the GA's crossover and mutation operations produce random numbers, the weights won't naturally sum to 1.0 (100%). We force this by summing the weights and dividing each by that sum.

#### 3. Fitness and Penalties
The `calculateFitness` function evaluates how "good" a solution is. 
*   **ROI:** It multiplies the weight by the category's ROI.
*   **Penalty:** To enforce the rule that "no category exceeds 40%," we check if any weight is `> 0.4`. If it is, we subtract a large value from the fitness score. This ensures that individuals violating the rules are unlikely to be selected for the next generation.

#### 4. Crossover and Mutation
*   **Crossover:** We pick a random "pivot" point. We take the first half of the weights from Parent A and the second half from Parent B.
*   **Mutation:** With a small probability (10%), we pick one weight and replace it with a random number, then re-normalize. This prevents the population from becoming identical too quickly.

#### 5. The Evolution Loop (`Run`)
*   **Sorting:** We use `sort.Slice` to rank individuals.
*   **Elitism:** We copy the top 10% of the population directly into the next generation. This ensures that our best solution never gets worse over time.
*   **Selection:** We pick parents from the top 20 performers to create children, ensuring that "good" traits are passed down.

### Why Go for this?
While the Python version is concise, the Go version is significantly faster. In a real-world scenario with thousands of categories or complex simulations for fitness, Go's ability to run `calculateFitness` in parallel using **Goroutines** would allow you to scale this algorithm to handle massive datasets efficiently.

Translating the **Capital Project Selection** problem into Go is an excellent way to understand how to handle discrete (Yes/No) decision-making using Genetic Algorithms. In this version, instead of percentages, our "DNA" consists of 0s and 1s.

Here is the Go implementation, followed by a beginner-friendly breakdown.

```python
package main

import (
	"fmt"
	"math/rand"
	"sort"
	"time"
)

// Project represents a business proposal
type Project struct {
	Name   string
	Cost   int
	Profit int
	Risk   int
}

// Individual represents a "candidate solution" (which projects to fund)
type Individual struct {
	Genes   []int   // e.g., [1, 0, 1] means fund project 1 and 3, but not 2
	Fitness float64 // The total profit (or 0 if it breaks rules)
}

// ProjectSelectionGA holds our settings
type ProjectSelectionGA struct {
	Projects     []Project
	BudgetLimit  int
	MaxRiskAvg   float64
	PopSize      int
	Generations  int
}

// NewGA is a helper to create our optimizer
func NewGA(projects []Project, budget int, maxRisk float64) *ProjectSelectionGA {
	return &ProjectSelectionGA{
		Projects:    projects,
		BudgetLimit: budget,
		MaxRiskAvg:  maxRisk,
		PopSize:     50,
		Generations: 100,
	}
}

// createIndividual creates a random binary string
func (ga *ProjectSelectionGA) createIndividual() Individual {
	genes := make([]int, len(ga.Projects))
	for i := range genes {
		genes[i] = rand.Intn(2) // Randomly picks 0 or 1
	}
	ind := Individual{Genes: genes}
	ind.Fitness = ga.calculateFitness(ind)
	return ind
}

// calculateFitness is the "Judge". It scores how good a solution is.
func (ga *ProjectSelectionGA) calculateFitness(ind Individual) float64 {
	totalCost := 0
	totalProfit := 0
	totalRisk := 0
	count := 0

	for i, selected := range ind.Genes {
		if selected == 1 {
			totalCost += ga.Projects[i].Cost
			totalProfit += ga.Projects[i].Profit
			totalRisk += ga.Projects[i].Risk
			count++
		}
	}

	// Rule 1: Don't go over budget
	if totalCost > ga.BudgetLimit {
		return 0
	}

	// Rule 2: Don't exceed average risk threshold
	if count > 0 {
		avgRisk := float64(totalRisk) / float64(count)
		if avgRisk > ga.MaxRiskAvg {
			return 0
		}
	}

	return float64(totalProfit)
}

// crossover mixes the genes of two parents
func (ga *ProjectSelectionGA) crossover(p1, p2 Individual) Individual {
	point := rand.Intn(len(ga.Projects))
	newGenes := make([]int, len(ga.Projects))

	// Take first half from parent 1, second half from parent 2
	copy(newGenes[:point], p1.Genes[:point])
	copy(newGenes[point:], p2.Genes[point:])

	return Individual{Genes: newGenes}
}

// mutate randomly flips a 0 to a 1 (or vice versa)
func (ga *ProjectSelectionGA) mutate(ind *Individual) {
	idx := rand.Intn(len(ga.Projects))
	if ind.Genes[idx] == 0 {
		ind.Genes[idx] = 1
	} else {
		ind.Genes[idx] = 0
	}
}

func (ga *ProjectSelectionGA) Run() Individual {
	rand.Seed(time.Now().UnixNano())

	// 1. Create initial random population
	population := make([]Individual, ga.PopSize)
	for i := 0; i < ga.PopSize; i++ {
		population[i] = ga.createIndividual()
	}

	for gen := 0; gen < ga.Generations; gen++ {
		// 2. Sort by fitness (highest profit first)
		sort.Slice(population, func(i, j int) bool {
			return population[i].Fitness > population[j].Fitness
		})

		// 3. Elitism: Keep the top 5 solutions automatically
		nextGen := make([]Individual, 0, ga.PopSize)
		nextGen = append(nextGen, population[:5]...)

		// 4. Breeding: Fill the rest of the population
		for len(nextGen) < ga.PopSize {
			// Pick two parents from the top 15
			p1 := population[rand.Intn(15)]
			p2 := population[rand.Intn(15)]

			child := ga.crossover(p1, p2)

			// 20% chance of mutation
			if rand.Float64() < 0.2 {
				ga.mutate(&child)
			}

			child.Fitness = ga.calculateFitness(child)
			nextGen = append(nextGen, child)
		}
		population = nextGen
	}

	return population[0] // Return the best one found
}

func main() {
	projects := []Project{
		{"AI Expansion", 200, 100, 8},
		{"New Warehouse", 150, 40, 3},
		{"R&D Lab", 300, 120, 6},
		{"Marketing Blitz", 100, 70, 5},
		{"Cybersecurity", 80, 30, 2},
		{"Fleet Upgrade", 120, 50, 4},
	}

	// Budget: $500k, Max Avg Risk: 5.0
	ga := NewGA(projects, 500, 5.0)
	best := ga.Run()

	fmt.Println("--- Optimal Project Selection ---")
	totalCost := 0
	for i, selected := range best.Genes {
		if selected == 1 {
			p := projects[i]
			fmt.Printf("Funded: %-15s | Cost: $%dk | Profit: $%dk\n", p.Name, p.Cost, p.Profit)
			totalCost += p.Cost
		}
	}
	fmt.Printf("\nTotal Budget Used: $%dk\n", totalCost)
	fmt.Printf("Total Expected Profit: $%.0fk\n", best.Fitness)
}
```

---

### Step-by-Step Explanation for Beginners

#### 1. The "DNA" (Genes)
In programming, we need a way to represent a solution. Since this is a "Yes/No" problem (Should we fund this project?), we use a **Slice of Integers** (`[]int`). 
*   `[1, 0, 1]` means: "Yes to Project A, No to Project B, Yes to Project C."
*   This is much simpler than the previous example where we used decimals for weights.

#### 2. The Fitness Function (The Judge)
The `calculateFitness` function is the most important part. It acts like a manager reviewing a budget proposal:
*   **Profit:** It adds up the profit of all projects marked with a `1`.
*   **Constraints:** If the total cost is over the budget ($500k) OR if the average risk is too high, the function returns `0`. 
*   **Why 0?** In a GA, a fitness of 0 is a "death sentence." It means this solution is invalid and shouldn't be allowed to have "children" in the next generation.

#### 3. Crossover (Breeding)
Imagine Parent A is good at picking low-risk projects and Parent B is good at picking high-profit projects. 
*   We pick a random point in their gene slice.
*   We take the beginning of Parent A's list and the end of Parent B's list and stitch them together.
*   The resulting "Child" might inherit the best traits from both.

#### 4. Mutation (Random Ideas)
If we only ever mixed existing parents, we might get stuck. Mutation introduces brand-new ideas. 
*   We pick one project at random and flip it: if it was "Funded" (1), it becomes "Not Funded" (0).
*   This helps the algorithm explore options that weren't in the original random population.

#### 5. The Evolution Loop (`Run`)
This is the engine of the program:
1.  **Initialize:** Create 50 random solutions.
2.  **Sort:** Rank them from highest profit to lowest.
3.  **Elitism:** We take the top 5 solutions and move them to the next generation unchanged. This ensures we never lose our "current best" idea.
4.  **Repeat:** We do this for 100 generations. By the end, the population has "evolved" toward the most profitable combination that fits the budget.

### Why use Go for this?
For a small list of 6 projects, any language is fine. However, if you were a large bank choosing between **10,000** different loans or projects, the number of possible combinations is astronomical. Go's speed and efficiency allow you to run thousands of generations across millions of possibilities in seconds, whereas a slower language might take minutes.

Translating the **Cash Flow Matching** problem into Go allows us to see how Go handles more complex data structures (like slices within structs) and how it manages optimization tasks efficiently.

In this scenario, we are trying to find the cheapest combination of bonds to ensure we have enough cash to pay off debts (liabilities) due every year for the next four years.

Per your instruction, the Go code is provided within the requested block format:

```python
package main

import (
	"fmt"
	"math/rand"
	"sort"
	"time"
)

// Bond represents a financial instrument we can buy
type Bond struct {
	Name    string
	Price   float64
	Coupons []float64 // Cash paid out each year (e.g., [Year1, Year2, Year3, Year4])
}

// Individual represents a "candidate portfolio"
type Individual struct {
	Quantities []int   // How many of each bond to buy (e.g., [2, 0, 5, 1])
	Fitness    float64 // The "score" (Cost + Penalties)
}

// CashFlowMatchingGA holds the configuration
type CashFlowMatchingGA struct {
	Bonds        []Bond
	Liabilities  []float64
	PopSize      int
	Generations  int
	MutationRate float64
}

// NewGA initializes the optimizer
func NewGA(bonds []Bond, liabilities []float64) *CashFlowMatchingGA {
	return &CashFlowMatchingGA{
		Bonds:        bonds,
		Liabilities:  liabilities,
		PopSize:      100,
		Generations:  500,
		MutationRate: 0.1,
	}
}

// calculateFitness determines how good a portfolio is
func (ga *CashFlowMatchingGA) calculateFitness(quantities []int) float64 {
	totalCost := 0.0
	yearlyCashFlows := make([]float64, len(ga.Liabilities))

	// Calculate total cost and cash generated per year
	for i, qty := range quantities {
		totalCost += float64(qty) * ga.Bonds[i].Price
		for year, amount := range ga.Bonds[i].Coupons {
			yearlyCashFlows[year] += float64(qty) * amount
		}
	}

	// Penalty: If we don't have enough cash to cover a liability in any year
	penalty := 0.0
	for year, liability := range ga.Liabilities {
		if yearlyCashFlows[year] < liability {
			// We apply a massive penalty for failing to meet a debt
			penalty += (liability - yearlyCashFlows[year]) * 5000
		}
	}

	// We want to MINIMIZE (Cost + Penalty). 
	// Since GAs usually maximize, we return a negative value.
	// The "highest" value will be the one closest to zero.
	return -(totalCost + penalty)
}

// createIndividual creates a random portfolio
func (ga *CashFlowMatchingGA) createIndividual() Individual {
	quantities := make([]int, len(ga.Bonds))
	for i := range quantities {
		quantities[i] = rand.Intn(11) // Buy between 0 and 10 units of each bond
	}
	return Individual{
		Quantities: quantities,
		Fitness:    ga.calculateFitness(quantities),
	}
}

// crossover mixes two portfolios
func (ga *CashFlowMatchingGA) crossover(p1, p2 Individual) Individual {
	point := rand.Intn(len(ga.Bonds))
	childQty := make([]int, len(ga.Bonds))
	copy(childQty[:point], p1.Quantities[:point])
	copy(childQty[point:], p2.Quantities[point:])

	return Individual{
		Quantities: childQty,
		Fitness:    ga.calculateFitness(childQty),
	}
}

// mutate randomly changes the quantity of one bond
func (ga *CashFlowMatchingGA) mutate(ind *Individual) {
	if rand.Float64() < ga.MutationRate {
		idx := rand.Intn(len(ga.Bonds))
		ind.Quantities[idx] = rand.Intn(11)
		ind.Fitness = ga.calculateFitness(ind.Quantities)
	}
}

func (ga *CashFlowMatchingGA) Run() Individual {
	rand.Seed(time.Now().UnixNano())

	// 1. Initialize Population
	population := make([]Individual, ga.PopSize)
	for i := 0; i < ga.PopSize; i++ {
		population[i] = ga.createIndividual()
	}

	for gen := 0; gen < ga.Generations; gen++ {
		// 2. Sort by Fitness (Highest value first)
		sort.Slice(population, func(i, j int) bool {
			return population[i].Fitness > population[j].Fitness
		})

		// 3. Elitism: Keep the top 10
		nextGen := make([]Individual, 0, ga.PopSize)
		nextGen = append(nextGen, population[:10]...)

		// 4. Breeding
		for len(nextGen) < ga.PopSize {
			p1 := population[rand.Intn(30)] // Select from top 30
			p2 := population[rand.Intn(30)]

			child := ga.crossover(p1, p2)
			ga.mutate(&child)
			nextGen = append(nextGen, child)
		}
		population = nextGen
	}

	return population[0]
}

func main() {
	// Yearly Liabilities: $1k, $2k, $1.5k, $3k
	debts := []float64{1000, 2000, 1500, 3000}

	marketBonds := []Bond{
		{"Bond A (4yr)", 950,  []float64{50, 50, 50, 1050}},
		{"Bond B (3yr)", 1020, []float64{100, 100, 1100, 0}},
		{"Bond C (2yr)", 980,  []float64{80, 1080, 0, 0}},
		{"Bond D (1yr)", 1000, []float64{1100, 0, 0, 0}},
	}

	ga := NewGA(marketBonds, debts)
	best := ga.Run()

	fmt.Println("--- Optimal Bond Portfolio ---")
	for i, qty := range best.Quantities {
		if qty > 0 {
			fmt.Printf("Buy %2d units of %-12s | Price: $%.2f\n", qty, marketBonds[i].Name, marketBonds[i].Price)
		}
	}

	fmt.Printf("\nTotal Portfolio Cost: $%.2f\n", -best.Fitness)
}
```

