import re

def validate_user_profile(data):
    """
    Validates the complete user profile data structure.

    :param data: Dictionary containing first_name, last_name, weight, height, and profile_pic_url
    :return: (bool, message)
    """
    # 1. Validate Names
    if not data.get('first_name') or not data.get('last_name'):
        return False, "First and last names are required."

    if len(data['first_name']) < 2 or len(data['last_name']) < 2:
