    # 2. Validate Physical Stats
    try:
        weight = float(data.get('weight', 0))
        height = float(data.get('height', 0))
        if weight <= 0 or height <= 0:
            return False, "Weight and height must be positive numbers."
    except (ValueError, TypeError):
        return False, "Weight and height must be numeric."

    # 3. Validate Profile Picture URL
    pic_url = data.get('profile_pic_url', '')
    if not pic_url.startswith('http'):
        return False, "A valid profile picture URL is required."

    return True, "Validation successful"

