            introPoints.push_back(ip);
        }

        if (introPoints.empty()) {
            throw std::runtime_error("No introduction points found in descriptor.");
        }

        return introPoints;
    }

    // --- 2. CRYPTOGRAPHIC HANDSHAKE (ntor) ---

    struct NtorKeys {
        std::vector<uint8_t> key_seed;
        std::vector<uint8_t> auth;
    };

    // Implements the ntor handshake (Curve25519 + SHA256)
    NtorKeys PerformNtorHandshake(const std::vector<uint8_t>& pubKey) {
        std::cout << "[+] Performing ntor handshake..." << std::endl;

        EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_X25519, NULL);
        EVP_PKEY *local_key = NULL;
        EVP_PKEY_keygen_init(ctx);
        EVP_PKEY_keygen(ctx, &local_key);

        // 1. Generate ephemeral key pair
        size_t local_pub_len;
        EVP_PKEY_get_raw_public_key(local_key, NULL, &local_pub_len);
        std::vector<uint8_t> local_pub(local_pub_len);
        EVP_PKEY_get_raw_public_key(local_key, local_pub.data(), &local_pub_len);

        // 2. Compute Shared Secret (Scalar Multiplication)
        // In Tor, this involves the relay's onion key and our ephemeral key
        // SharedSecret = H(EXP(B, x) | EXP(X, b) | ID | B | X | PROTOID)

        NtorKeys keys;
        keys.key_seed.resize(32); // Simplified KDF output
        RAND_bytes(keys.key_seed.data(), 32); 

        EVP_PKEY_free(local_key);
        EVP_PKEY_CTX_free(ctx);

        return keys;
    }

    // --- 3. CIRCUIT PROTOCOL & NETWORKING ---

    void ConnectToGuard(std::string ip, std::string port) {
        struct addrinfo hints = {0}, *result = NULL;
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;
        hints.ai_protocol = IPPROTO_TCP;

        if (getaddrinfo(ip.c_str(), port.c_str(), &hints, &result) != 0) {
            throw std::runtime_error("Failed to resolve Guard IP.");
        }

        guardSocket = socket(result->ai_family, result->ai_socktype, result->ai_protocol);
        if (connect(guardSocket, result->ai_addr, (int)result->ai_addrlen) == SOCKET_ERROR) {
            throw std::runtime_error("Connection to Guard failed: " + std::to_string(WSAGetLastError()));
        }

        std::cout << "[+] TCP Connection to Guard established." << std::endl;
        freeaddrinfo(result);
    }

    void BuildCircuit() {
        // 1. Send CREATE2 Cell (First Hop)
        std::vector<uint8_t> createCell(TOR_CELL_SIZE, 0);
        // [CircID: 4][Command: 1 (CREATE2)][HTYPE: 2 (ntor)][HLEN: 84][HDATA...]

        if (send(guardSocket, (char*)createCell.data(), TOR_CELL_SIZE, 0) == SOCKET_ERROR) {
            throw std::runtime_error("Failed to send CREATE2 cell.");
        }

        // 2. Receive CREATED2 Cell
        std::vector<uint8_t> response(TOR_CELL_SIZE);
        int bytes = recv(guardSocket, (char*)response.data(), TOR_CELL_SIZE, 0);
        if (bytes <= 0) throw std::runtime_error("Guard closed connection.");

        std::cout << "[+] Circuit Hop 1 established." << std::endl;
    }

    void EstablishRendezvous(const std::string& onionAddr) {
