#include <winhttp.h>
#include <winsock2.h>
#include <openssl/err.h>
#include <openssl/evp.h>
#include <iostream>
#include <vector>
#include <string>
#include <stdexcept>

#pragma comment(lib, "winhttp.lib")

class TorV3RequestClient {
private:
    HINTERNET hSession = NULL;
    std::wstring proxyAddress = L"127.0.0.1:9050"; // The local port our Tor circuit logic listens on

    // --- Error Handling Helpers ---

    void ThrowWinHttpError(const std::string& context) {
        DWORD dwError = GetLastError();
        char errorMsg[256];
        FormatMessageA(FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
                       NULL, dwError, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
                       errorMsg, sizeof(errorMsg), NULL);
        throw std::runtime_error(context + " failed: " + std::string(errorMsg) + " (Code: " + std::to_string(dwError) + ")");
    }

    void ThrowCryptoError(const std::string& context) {
        unsigned long err = ERR_get_error();
        char buf[256];
        ERR_error_string_n(err, buf, sizeof(buf));
        throw std::runtime_error("Cryptographic Failure during " + context + ": " + std::string(buf));
    }

public:
    TorV3RequestClient() {
        // Initialize OpenSSL error strings
        ERR_load_crypto_strings();
        OpenSSL_add_all_algorithms();

        // Initialize WinHTTP Session
        // We specify WINHTTP_ACCESS_TYPE_NAMED_PROXY to route through our custom Tor circuit
        hSession = WinHttpOpen(L"TorV3StandaloneClient/3.0", 
                               WINHTTP_ACCESS_TYPE_NAMED_PROXY,
                               proxyAddress.c_str(), 
                               WINHTTP_NO_PROXY_BYPASS, 0);

        if (!hSession) ThrowWinHttpError("WinHttpOpen");
    }

    ~TorV3RequestClient() {
        if (hSession) WinHttpCloseHandle(hSession);
        EVP_cleanup();
        ERR_free_strings();
    }

    // --- Core Request Logic ---

    std::string SendRequest(const std::string& onionUrl, const std::string& method, const std::string& postData = "") {
        HINTERNET hConnect = NULL, hRequest = NULL;
        std::string responseData;
        URL_COMPONENTS urlComp = { 0 };
        wchar_t hostName[256], urlPath[1024];

        try {
            // 1. Parse the .onion URL
            urlComp.dwStructSize = sizeof(urlComp);
            urlComp.lpszHostName = hostName;
            urlComp.dwHostNameLength = sizeof(hostName) / sizeof(wchar_t);
            urlComp.lpszUrlPath = urlPath;
            urlComp.dwUrlPathLength = sizeof(urlPath) / sizeof(wchar_t);

            std::wstring wUrl(onionUrl.begin(), onionUrl.end());
            if (!WinHttpCrackUrl(wUrl.c_str(), (DWORD)wUrl.length(), 0, &urlComp)) {
                ThrowWinHttpError("URL Parsing");
            }

            // 2. Connect to the Hidden Service (via Proxy)
            hConnect = WinHttpConnect(hSession, hostName, urlComp.nPort, 0);
            if (!hConnect) ThrowWinHttpError("WinHttpConnect");

            // 3. Open Request
            std::wstring wMethod(method.begin(), method.end());
            hRequest = WinHttpOpenRequest(hConnect, wMethod.c_str(), urlComp.lpszUrlPath,
                                          NULL, WINHTTP_NO_REFERER, 
                                          WINHTTP_DEFAULT_ACCEPT_TYPES, 
                                          (urlComp.nScheme == INTERNET_SCHEME_HTTPS) ? WINHTTP_FLAG_SECURE : 0);
            if (!hRequest) ThrowWinHttpError("WinHttpOpenRequest");

            // 4. Set Timeouts (Tor can be slow, so we increase these)
            WinHttpSetTimeouts(hRequest, 30000, 60000, 30000, 60000);

            // 5. Send Request
            BOOL bResults = FALSE;
            if (method == "POST") {
                std::wstring headers = L"Content-Type: application/json\r\n";
                bResults = WinHttpSendRequest(hRequest, headers.c_str(), (DWORD)-1L, 
                                              (LPVOID)postData.c_str(), (DWORD)postData.length(), 
                                              (DWORD)postData.length(), 0);
            } else {
                bResults = WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0, 
                                              WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
            }

            if (!bResults) ThrowWinHttpError("WinHttpSendRequest");

            // 6. Receive Response
            if (!WinHttpReceiveResponse(hRequest, NULL)) ThrowWinHttpError("WinHttpReceiveResponse");

            // 7. Read Data
            DWORD dwSize = 0;
            do {
                if (!WinHttpQueryDataAvailable(hRequest, &dwSize)) ThrowWinHttpError("WinHttpQueryDataAvailable");
                if (dwSize == 0) break;

                std::vector<char> buffer(dwSize + 1);
                DWORD dwDownloaded = 0;
                if (!WinHttpReadData(hRequest, (LPVOID)buffer.data(), dwSize, &dwDownloaded)) {
                    ThrowWinHttpError("WinHttpReadData");
                }
                responseData.append(buffer.data(), dwDownloaded);
            } while (dwSize > 0);

        } catch (...) {
            if (hRequest) WinHttpCloseHandle(hRequest);
            if (hConnect) WinHttpCloseHandle(hConnect);
            throw; // Re-throw to be caught in main
        }

        if (hRequest) WinHttpCloseHandle(hRequest);
        if (hConnect) WinHttpCloseHandle(hConnect);

        return responseData;
    }

    // --- Cryptographic Integrity Check ---
    // Example: Verifying a signature from the HS response using OpenSSL
    bool VerifyResponseIntegrity(const std::string& data, const std::vector<uint8_t>& signature, EVP_PKEY* pubKey) {
        EVP_MD_CTX* m_RSAVerifyCtx = EVP_MD_CTX_new();
        if (EVP_DigestVerifyInit(m_RSAVerifyCtx, NULL, EVP_sha256(), NULL, pubKey) <= 0) {
            EVP_MD_CTX_free(m_RSAVerifyCtx);
            ThrowCryptoError("EVP_DigestVerifyInit");
        }

        int result = EVP_DigestVerifyUpdate(m_RSAVerifyCtx, data.data(), data.size());
        if (result <= 0) {
            EVP_MD_CTX_free(m_RSAVerifyCtx);
            ThrowCryptoError("EVP_DigestVerifyUpdate");
        }

        result = EVP_DigestVerifyFinal(m_RSAVerifyCtx, signature.data(), signature.size());
        EVP_MD_CTX_free(m_RSAVerifyCtx);

        return result == 1;
    }
};

