        std::cout << "[*] Sending GET request to Hidden Service..." << std::endl;
        std::string getResponse = client.SendRequest(onionAddr, "GET");
        std::cout << "[+] GET Response: " << getResponse << std::endl;

        std::cout << "\n[*] Sending POST request to Hidden Service..." << std::endl;
        std::string postData = "{\"action\":\"sync\",\"payload\":\"test_data\"}";
        std::string postResponse = client.SendRequest(onionAddr, "POST", postData);
        std::cout << "[+] POST Response: " << postResponse << std::endl;

    } catch (const std::exception& e) {
