    std::vector<uint8_t> DecryptDescriptorLayer(const std::vector<uint8_t>& ciphertext, const std::vector<uint8_t>& key) {
        std::cout << "[*] Decrypting HSv3 Descriptor Layer..." << std::endl;

        if (key.size() != 32) throw std::invalid_argument("AES-256 key must be 32 bytes.");

        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        std::vector<uint8_t> plaintext(ciphertext.size());
        std::vector<uint8_t> iv(16, 0); // Tor v3 uses specific IV derivation from the descriptor salt
        int len, outlen;

        if (EVP_DecryptInit_ex(ctx, EVP_aes_256_ctr(), NULL, key.data(), iv.data()) <= 0) {
            EVP_CIPHER_CTX_free(ctx);
            ThrowCryptoError("EVP_DecryptInit");
        }

        if (EVP_DecryptUpdate(ctx, plaintext.data(), &len, ciphertext.data(), (int)ciphertext.size()) <= 0) {
            EVP_CIPHER_CTX_free(ctx);
            ThrowCryptoError("EVP_DecryptUpdate");
        }
        outlen = len;

        if (EVP_DecryptFinal_ex(ctx, plaintext.data() + len, &len) <= 0) {
            EVP_CIPHER_CTX_free(ctx);
            ThrowCryptoError("EVP_DecryptFinal (Decryption Failure)");
        }
        outlen += len;

        EVP_CIPHER_CTX_free(ctx);
        return plaintext;
