As a mechatronics engineer, transitioning this model from Python to MATLAB is a natural step, as MATLAB/Simulink is the industry standard for automotive control systems. 

In MATLAB, we typically structure this as a main script with local functions at the bottom, or as a Simulink model. Below is the script-based implementation following MATLAB coding standards.

```python
% ABS_Simulation.m
% Mechatronics Engineering - Quarter Car ABS Model
% This script simulates a braking event with a Bang-Bang ABS controller.

clear; clc; close all;

%% --- Parameters ---
m = 450;          % kg (Mass of 1/4 car)
R = 0.3;          % m (Wheel radius)
J = 1.5;          % kg*m^2 (Wheel moment of inertia)
g = 9.81;         % m/s^2
K_brake = 0.15;   % Brake torque constant (Pressure to Torque)
dt = 0.001;       % Time step (1ms)
t_end = 5.0;      % Max simulation duration

%% --- Initial Conditions ---
v = 30.0;         % m/s (Initial velocity ~108 km/h)
omega = v / R;    % rad/s (Initial angular velocity)
P = 0.0;          % Initial brake pressure (Pa)

% Pre-allocation for performance
time_hist = 0:dt:t_end;
v_hist = zeros(size(time_hist));
omega_hist = zeros(size(time_hist));
slip_hist = zeros(size(time_hist));
P_hist = zeros(size(time_hist));

%% --- Main Simulation Loop ---
stop_idx = length(time_hist);

for i = 1:length(time_hist)
    t = time_hist(i);

    % 1. Calculate Slip
    s = slip_function(v, omega, R);

    % 2. Get Friction Coefficient (Tire Model)
    mu = tiremodel(s);
    F_z = m * g;
    F_x = mu * F_z;  % Longitudinal Braking Force

    % 3. ABS Control Logic
    % Driver's requested pressure (Ramp function)
    driver_request = ramp_function(t, 0.1, 1500000); 

    % ABS modulates the pressure based on slip
    P = ABScycle(s, P, 0.2, dt);

    % Pressure cannot exceed what the driver is providing
    P = min(P, driver_request);

    % Convert pressure to mechanical torque
    Tb = Braking_torque(P, K_brake);

    % 4. Equations of Motion (Euler Integration)
    % Vehicle Dynamics: dv/dt = -Fx / m
    dv = (-F_x / m) * dt;
    v = v + dv;
    if v < 0, v = 0; end % Car has stopped

    % Wheel Dynamics: d_omega/dt = (Fx*R - Tb) / J
    d_omega = ((F_x * R - Tb) / J) * dt;
    omega = omega + d_omega;
    if omega < 0, omega = 0; end

    % Store results
    v_hist(i) = v;
    omega_hist(i) = omega * R; % Store as linear velocity for comparison
    slip_hist(i) = s;
    P_hist(i) = P;

    % Terminate if car stops
    if v <= 0
        stop_idx = i;
        break;
    end
end

% Trim arrays to actual stop time
time_hist = time_hist(1:stop_idx);
v_hist = v_hist(1:stop_idx);
omega_hist = omega_hist(1:stop_idx);
slip_hist = slip_hist(1:stop_idx);

%% --- Plotting ---
figure('Name', 'ABS Simulation Results', 'Color', 'w');

subplot(2,1,1);
plot(time_hist, v_hist, 'LineWidth', 2, 'DisplayName', 'Vehicle Speed (v)');
hold on;
plot(time_hist, omega_hist, '--', 'LineWidth', 1.5, 'DisplayName', 'Wheel Speed (\omega R)');
title('ABS Simulation - Mechatronics System Response');
ylabel('Velocity (m/s)');
legend('Location', 'northeast');
grid on;

subplot(2,1,2);
plot(time_hist, slip_hist, 'r', 'LineWidth', 1.5, 'DisplayName', 'Slip Ratio');
hold on;
yline(0.2, 'k:', 'Target Slip (0.2)', 'LineWidth', 1.5);
ylabel('Slip (\lambda)');
xlabel('Time (s)');
ylim([0 1]);
legend();
grid on;

%% --- Supporting Functions ---

function s = slip_function(v, omega, R)
    % Calculates the longitudinal slip ratio
    if v < 0.1
        s = 0;
    else
        s = (v - omega * R) / v;
    end
end

function mu = tiremodel(slip)
    % Simplified Pacejka Magic Formula for dry asphalt
    B = 10; C = 1.9; D = 1.0; E = 0.97;
    mu = D * sin(C * atan(B * slip - E * (B * slip - atan(B * slip))));
end

function p_out = ramp_function(t, start_time, slope)
    % Simulates the driver pressing the brake pedal
    if t > start_time
        p_out = slope * (t - start_time);
    else
        p_out = 0;
    end
end

function Tb = Braking_torque(P, K_brake)
    % Converts hydraulic pressure to mechanical torque
    Tb = P * K_brake;
end

function new_pressure = ABScycle(current_slip, current_pressure, target_slip, dt)
    % Simple Bang-Bang ABS Controller
    % pressure_rate in Pa/s
    pressure_rate = 1000000; 

    if current_slip > target_slip
        % Slip too high: Release pressure to prevent lock-up
        new_pressure = current_pressure - (pressure_rate * dt);
    else
        % Slip low: Increase pressure to maximize braking
        new_pressure = current_pressure + (pressure_rate * dt);
    end

    if new_pressure < 0, new_pressure = 0; end
end
