fn run_init() {
    println!("[sysx] Initializing Devuan system...");

    // 1. Prepare the environment
    mount_essentials();
    setup_network();

    // 2. Shared state for task management
    // We use Arc<Mutex<...>> because the control socket runs in a separate 
    // thread from the main zombie-reaping loop.
    let tasks: Arc<Mutex<HashMap<u32, Task>>> = Arc::new(Mutex::new(HashMap::new()));

    // 3. Start the Control Socket Thread
    // This allows the 'sysx' CLI to talk to the init process.
    let tasks_clone = Arc::clone(&tasks);
    thread::spawn(move || {
        start_control_socket(tasks_clone);
    });

    // 4. Launch default system services
    launch_default_services();

    // 5. Start the primary console shell
    println!("[sysx] Starting login shell on tty1...");
    let _ = Command::new("/bin/sh")
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .env("HOME", "/root")
        .env("TERM", "linux")
        .spawn();

    // 6. Main Loop: Zombie Reaping
    // In Linux, when a child process dies, it becomes a 'zombie' until its 
    // parent calls 'wait'. As PID 1, we must reap all orphaned processes.
    loop {
        let mut status = 0;
        unsafe {
            // waitpid(-1, ...) waits for any child process.
            // WNOHANG ensures we don't block the loop if no process has exited.
            let pid = libc::waitpid(-1, &mut status, libc::WNOHANG);
            if pid > 0 {
                let mut t = tasks.lock().unwrap();
                // Remove the task from our tracking map if it was a managed service.
                t.retain(|_, task| task.pid != pid as u32);
            }
        }
        thread::sleep(std::time::Duration::from_millis(500));
    }
}

