    if not isinstance(raw_ingredients, list) or len(raw_ingredients) == 0:
        return jsonify({"error": "Invalid input"}), 400

    # Sanitize and limit the number of ingredients processed
    ingredients = [sanitize_input(str(i))[:30] for i in raw_ingredients[:5]]

    try:
        # 3. Gather Research
        internet_research = gather_internet_lore(ingredients)

        # 4. AI Generation with strict system instructions for coherence
        response = openai.ChatCompletion.create(
            model="gpt-3.5-turbo",
            messages=[
                {"role": "system", "content": "You are a helpful assistant that creates poetic, coherent kitchen spells based on folklore. Ensure the tone is mystical but safe."},
                {"role": "user", "content": f"""
