                const x = centerX + Math.cos(angle) * visualDist;
                const y = centerY + Math.sin(angle) * visualDist;

                ctx.beginPath();
                ctx.arc(centerX, centerY, visualDist, 0, Math.PI * 2);
                ctx.strokeStyle = "rgba(255, 255, 255, 0.05)";
                ctx.stroke();

